window.ROUTE_CHENGYE = {"id":"chengye","name":"程野","floor":20,"flag1Week":30,"flag2Week":39,"flag1Need":60,"flag2Need":80,"flag1Label":"护腕","flag2Label":"球场","tagline":"「他跑得很快，也从不落下朋友。」","chapters":[{"id":"extra","title":"番外 · 初中","scenes":[{"no":1,"title":"六张桌子","week":3,"bg":"izakaya_night","cast":["chengye"],"steps":[{"t":"cast","list":["chengye"],"focus":"chengye"},{"t":"n","text":"雨是突然下的。你背着书包往巷子里跑，跑到一半就湿了。"},{"t":"n","text":"巷口有家小饭馆，卷帘门只拉起来一半。你站在门口那块塑料雨棚下面，把书包抱在怀里。"},{"t":"n","text":"招牌是四个字：「程家小馆」。第二个字的漆掉了一半，露出底下的白铁皮。"},{"t":"n","text":"门里有人端着一盆水出来，往街面上泼。水花溅到你鞋上。"},{"t":"n","text":"他「哎」了一声，把盆往地上一放。"},{"t":"c","id":"chengye","text":"对不起对不起。没看见人。"},{"t":"n","text":"他比你高半个头，穿着校服，袖子卷到胳膊肘，胳膊上有一道晒出来的分界线。"},{"t":"n","text":"他把盆往门边一推，掀起塑料门帘。"},{"t":"c","id":"chengye","text":"进来躲啊。站外面干嘛，雨越下越大。"},{"t":"n","text":"你进去了。六张桌子，铺着格子的塑料桌布，其中一张缺了个角，用胶带粘过。"},{"t":"n","text":"墙上挂着一台旧空调，滴水，底下接了个红色的塑料桶。天花板上的风扇转得很慢，像在打瞌睡。"},{"t":"n","text":"后厨传来一声：「小野，三号桌的茄子！」"},{"t":"c","id":"chengye","text":"来了！"},{"t":"n","text":"他跑进去的时候，鞋底在湿瓷砖上打了个滑，手在门框上扶了一下，稳住了。"},{"t":"n","text":"你挑了靠墙的位子坐下。塑料菜单递过来，边角卷着，用透明胶封过好几遍。"},{"t":"n","text":"他端着一盘菜从你旁边过去，顺手放下一杯水。杯子上印着「某某汽水」，字已经洗淡了。"},{"t":"c","id":"chengye","text":"喝水不要钱。"},{"t":"n","text":"说完他又走了。围裙的带子在背后系了个死结，一高一低。"},{"t":"n","text":"冰柜侧面贴着一张奖状，被油烟熏黄了，边角翘起来。上面写着：校运动会，男子八百米，第一名。"},{"t":"n","text":"奖状底下压着一张手写的纸：「本店可赊账」。三个字写得很端正，跟奖状上的名字不是一个人的笔迹。"},{"t":"n","text":"菜单上的价格用圆珠笔改过。原来「六块」的，被划掉，改成「八块」。改了三处。"},{"t":"n","text":"后厨有人在哼歌，哼得很轻，跑调。哼两句，停一下，再哼。"},{"t":"n","text":"他端菜出来的时候，也跟着哼了两句，看见你，立刻停了。"},{"t":"n","text":"收银台后面贴着一张日历，翻到这一页，上面有几个日子被圆圈圈住。圈的都是周末。"},{"t":"n","text":"「周末人多。」他说，「我妈一个人忙不过来。」"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"点一碗面，坐着吃完","hint":"先吃点东西 · 不急","eff":{"aff":3.0,"happy":2.0,"fin":-1.0},"reply":[{"t":"n","text":"你说要一碗阳春面。他说「好嘞」，声音很响，把后厨的帘子掀起来喊了一声。"},{"t":"n","text":"面上来的时候，上面卧了一个荷包蛋。你说你没点蛋。"},{"t":"c","id":"chengye","text":"送的。今天蛋便宜。"},{"t":"n","text":"后厨的帘子掀开一条缝，他妈妈探头看了一眼，没说话，又缩回去了。"},{"t":"n","text":"面很烫。你吃到一半，他已经来回端了三趟菜，每次经过都要看一眼你的碗。"},{"t":"n","text":"第三趟的时候他停下来，说：「汤淡不淡。」"},{"t":"n","text":"你说刚好。"},{"t":"n","text":"他点头，走了两步又回头。"},{"t":"c","id":"chengye","text":"淡了就说。我们家汤可以淡，面不能坨。"},{"t":"n","text":"结账八块。他从围裙口袋里掏出一把零钱，一张一张数，数了两遍，找回你两块。"}]},{"label":"B","text":"帮他端两趟菜","hint":"搭一把手 · 他会记很久","eff":{"aff":5.0,"str":1.0,"eq":1.0},"reply":[{"t":"n","text":"你把书包放到椅子上，说，我帮你端。"},{"t":"n","text":"他愣了一下，把手里那盘茄子递给你，说：「那桌，靠窗的。慢点啊，烫。」"},{"t":"n","text":"你端过去的时候，汤晃出来一点，落在手背上。是凉的。"},{"t":"n","text":"他看见了，抓过你的手翻过来看，说：「没事没事，凉的。」"},{"t":"n","text":"后厨传来一句：「小野，你别让人家干活。」"},{"t":"c","id":"chengye","text":"人家自己要帮的！"},{"t":"n","text":"后厨安静了两秒，说：「那你不会说谢谢啊。」"},{"t":"n","text":"他挠了挠头，很认真地说：「谢谢啊。」"}]}]},{"t":"n","text":"雨停得比想象中快。你走的时候，他站在门口，围裙还没解。"},{"t":"c","id":"chengye","text":"下次来啊。报我名字，送你蛋。"},{"t":"n","text":"你问他叫什么。"},{"t":"n","text":"他愣了一下，好像这个问题有点突然。"},{"t":"c","id":"chengye","text":"程野。程序的程，野——野草的野。"},{"t":"n","text":"后厨喊他，他应了一声，跑回去。塑料门帘啪地打在他背上。"}],"id":"chengye_01"},{"no":2,"title":"最后一棒","week":6,"bg":"court_day","cast":["chengye"],"steps":[{"t":"cast","list":["chengye"],"focus":"chengye"},{"t":"n","text":"校运会那天很晒。跑道是煤渣铺的，白线掉了一半色，跑起来会扬起一小片灰。"},{"t":"n","text":"四乘一百接力，他跑最后一棒。前三棒跑完，你们班第三。"},{"t":"n","text":"他站在接力区，身体前倾，右手往后伸着。号码布用别针别在胸前，别歪了，一角翘起来。"},{"t":"n","text":"第三棒过来的时候，他的手和棒子差了半拍。"},{"t":"n","text":"他往前捞了一下，抓住了。"},{"t":"n","text":"看台上有人喊。他跑出去，鞋底在煤渣上打了一下滑，然后稳住了。"},{"t":"n","text":"最后五十米，他追上了第二。"},{"t":"n","text":"冲线以后，他没有举手，也没有喊。他弯下腰，撑着膝盖，喘。"},{"t":"n","text":"然后他直起身，往回跑。"},{"t":"n","text":"隔壁班一个男生摔在第三棒的位置，坐在地上，膝盖破了。"},{"t":"n","text":"程野跑过去，蹲下来，把那个男生的胳膊架到自己肩上，一路扶到跑道外面。"},{"t":"n","text":"体育老师在终点那边喊：「程野！领奖！」"},{"t":"n","text":"他抬了下手，意思是等一下。"},{"t":"n","text":"你走过去的时候，他正蹲着给那个男生吹膝盖上的灰。"},{"t":"c","id":"chengye","text":"别吹。越吹越脏。"},{"t":"n","text":"他抬头看见你，脸上还带着跑完的红。"},{"t":"c","id":"chengye","text":"我刚才追了两个。"},{"t":"n","text":"你说，三个。还有一个没追上。"},{"t":"n","text":"他停了一下，笑了一声。"},{"t":"c","id":"chengye","text":"也是。"},{"t":"n","text":"他站起来，抬手要把号码布扯下来，扯了一下没扯动。别针勾住了校服。"},{"t":"n","text":"他低头看。别针歪着，一头已经扎进布料里，另一头露在外面。"},{"t":"c","id":"chengye","text":"帮我弄一下。"},{"t":"n","text":"你伸手把别针解开。针尖有点钝，扎了两下才穿过去。"},{"t":"n","text":"你重新别好，在号码布的四个角各别了一个。"},{"t":"n","text":"他站直了，挺起胸让你看。"},{"t":"c","id":"chengye","text":"正不正。"},{"t":"n","text":"你说歪了。"},{"t":"n","text":"他低头看了半天，看不见，索性把胸挺得更直一点。"},{"t":"c","id":"chengye","text":"歪就歪吧。反正跑的时候没人看。"},{"t":"n","text":"他低头摸了摸那四个别针，摸了一圈。"},{"t":"c","id":"chengye","text":"你别说，还挺稳。"},{"t":"n","text":"广播在念名次。他蹲下去解鞋带，把鞋脱了，倒过来抖了抖，掉出一粒小石子。"},{"t":"n","text":"脚趾上有个水泡，破了，皮翻着。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"把水瓶递给他","hint":"先喝口水 · 别急着说","eff":{"aff":3.0,"happy":2.0,"str":1.0},"reply":[{"t":"n","text":"他接过去，仰头喝了大半瓶，剩下的浇在手上，抹了一把脸。"},{"t":"n","text":"「爽。」他说，把空瓶捏扁，塞进裤兜里。"},{"t":"n","text":"他捏瓶子的力气很大，塑料在他手里发出很响的一声。"}]},{"label":"B","text":"问他为什么板着脸","hint":"问一句 · 他会说实话","eff":{"aff":4.0,"eq":2.0,"happy":1.0},"reply":[{"t":"n","text":"他低头把鞋带重新系上。"},{"t":"c","id":"chengye","text":"我跑最后一棒，就是拿来追的。"},{"t":"n","text":"他把鞋带拉紧，打了一个很死的结。"},{"t":"c","id":"chengye","text":"追不上，就是我慢。"}]},{"label":"C","text":"陪他把摔倒的男生送去医务室","hint":"跟他走一趟 · 路不长","eff":{"aff":5.0,"str":1.0,"happy":2.0},"reply":[{"t":"n","text":"医务室在教学楼后面，要绕过一整个操场。"},{"t":"n","text":"那个男生一路说「我自己能走」。程野说「你走你的，我扶我的」。"},{"t":"n","text":"把人送到，他出来的时候，在走廊上站了一会儿。"},{"t":"c","id":"chengye","text":"跑得快有什么用。他摔了，我还是得跑回去。"},{"t":"n","text":"你说，那你不是跑回去了吗。"},{"t":"n","text":"他看了你一眼，没说话。过了一会儿，他说：「也是。」"}]}]},{"t":"n","text":"傍晚清场，他一个人把接力棒送回器材室。你跟过去。"},{"t":"n","text":"器材室里有一股橡胶味。他把棒子放回筐里，摆得很正。"},{"t":"n","text":"筐里一共十二根，他数了一遍，又倒过来数了一遍。"},{"t":"c","id":"chengye","text":"少一根。上次比赛丢的。"},{"t":"n","text":"他蹲下去，把筐底那几根也翻出来看。"},{"t":"n","text":"他挑出一根，握了握，说：「这根太滑。」然后放回去，换了一根。"},{"t":"c","id":"chengye","text":"明天补一根。"},{"t":"c","id":"chengye","text":"明天早读前我要来跑两圈。你来不来。"},{"t":"n","text":"你说来。"},{"t":"c","id":"chengye","text":"六点半啊。迟到不等。"},{"t":"n","text":"第二天你到的时候，他已经跑完了。衣服湿透，坐在台阶上喝水。"},{"t":"n","text":"他把水瓶递给你，说：「你迟到了四分钟。我多跑了一圈。」"}],"id":"chengye_02"},{"no":3,"title":"左眉上的疤","week":9,"bg":"izakaya_night","cast":["chengye"],"steps":[{"t":"cast","list":["chengye"],"focus":"chengye"},{"t":"n","text":"他请了两天假。班主任让你把作业送过去。"},{"t":"n","text":"饭馆已经打烊了，卷帘门拉下来，只留旁边一扇小门。灯只开了一半。"},{"t":"n","text":"他一个人在擦桌子。桌上摞着椅子，抹布从他手里掉下来，他弯腰去捡。"},{"t":"n","text":"他妈妈坐在收银台后面数钱。一沓零钱，一张一张抹平，摞成一叠。"},{"t":"n","text":"收银台上放着一张单子。红色的抬头，盖了一个方章。"},{"t":"n","text":"你走近了才看清：燃气管道整改通知，限期一个月，费用三千八。"},{"t":"n","text":"你把作业放在桌上。他说了一声「放那儿吧」，没抬头。"},{"t":"n","text":"他擦到你脚边的时候，你看见他左眉上那道疤。很浅，白色的，从眉毛中间斜着划过去。"},{"t":"n","text":"你问了一句。"},{"t":"n","text":"他把抹布搭在肩上，想了一下。"},{"t":"c","id":"chengye","text":"七岁。门口那个三轮车，溜坡。"},{"t":"n","text":"他指了指门外。"},{"t":"c","id":"chengye","text":"车上装的煤气罐。我妈在后面推，我在前面挡。"},{"t":"n","text":"他说得很轻松，像在说别人的事。"},{"t":"c","id":"chengye","text":"缝了三针。我没哭。"},{"t":"n","text":"收银台那边传来一句：「哭了。」"},{"t":"n","text":"他妈妈没有抬头，继续数钱。"},{"t":"c","id":"chengye","text":"妈。"},{"t":"n","text":"他妈妈把钱摞好，用一根皮筋捆上。"},{"t":"n","text":"「哭得整条巷子都听见了。」她说，「抱着我的腿，说什么也不撒手。」"},{"t":"n","text":"他耳朵红了。他把抹布往水桶里一扔，说：「我那时候小。」"},{"t":"n","text":"「七岁。」他妈妈说。"},{"t":"n","text":"她把皮筋解开，重新数了一遍。数到一半停下来，把一张卷了角的十块钱抹平。"},{"t":"n","text":"你看见她的手。指关节很大，虎口有一道裂口，贴着创可贴，创可贴的边已经黑了。"},{"t":"n","text":"她数完，把钱放进一个铁盒子，盖上，塞到收银台底下。"},{"t":"n","text":"程野把抹布挂好，走过来，从她手里把铁盒接过去，放得更深一点。"},{"t":"n","text":"「你放那么深干嘛。」她说。"},{"t":"n","text":"「怕丢。」他说。"},{"t":"n","text":"她笑了一下，抬手在他背上拍了一下。拍得很轻。"},{"t":"n","text":"铁盒在柜台下面碰到什么东西，响了一声。他的动作停了半秒，才把手抽出来。"},{"t":"n","text":"铁盒上印着饼干的牌子，红的，掉了漆。用了很多年。"},{"t":"n","text":"「这个盒子比我还大。」他说，「我小时候以为里面全是钱。」"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"帮他把椅子搬上桌","hint":"手上有点事 · 话好说","eff":{"aff":4.0,"str":1.0,"happy":1.0},"reply":[{"t":"n","text":"椅子是铁的，腿有点晃。你搬起第一把的时候，他说「哎我来」，你说不用。"},{"t":"n","text":"两个人搬完六张桌子，谁也没说话。"},{"t":"n","text":"搬到最后一张，他忽然说：「你搬椅子的样子，跟我妈一样。先抬一头。」"}]},{"label":"B","text":"问他那笔钱怎么办","hint":"问得直接 · 他不躲","eff":{"aff":2.0,"eq":2.0,"stress":1.0},"reply":[{"t":"n","text":"他把抹布拧干，挂在水龙头上。水是黑的。"},{"t":"n","text":"「这条街的下水道堵。」他说，「一到冬天就堵。」"},{"t":"n","text":"他把盆里的水倒掉，又接了一盆。"},{"t":"c","id":"chengye","text":"不知道。先拖着。"},{"t":"n","text":"他看了一眼那张单子，又移开视线。"},{"t":"c","id":"chengye","text":"我妈说，先把灶修了。管子以后再说。"},{"t":"n","text":"你说那不安全。他说：「我知道。」"}]},{"label":"C","text":"陪他算一算这个月还差多少","hint":"把数字摆出来 · 心里有底","eff":{"aff":5.0,"int":1.0,"happy":1.0},"reply":[{"t":"n","text":"他从收银台底下抽出一张纸，背面是打印的菜单。"},{"t":"n","text":"六张桌子，一天翻台三次，一碗面八块，一桌平均三十四。他一边念一边写，写得飞快。"},{"t":"n","text":"你算到一半还在想，他已经报了总数。"},{"t":"n","text":"你说，你数学挺好的。"},{"t":"n","text":"他抬起头，笑了一下，那个笑有点短。"},{"t":"c","id":"chengye","text":"这是算钱，不是数学。"},{"t":"n","text":"他把笔放下。"},{"t":"c","id":"chengye","text":"我数学三十八分。"}]}]},{"t":"n","text":"你走的时候，他妈妈塞给你一袋酥肉，用油纸包着。"},{"t":"n","text":"「拿回去给你妈尝尝。」她说。"},{"t":"n","text":"他送你到巷口。路灯只亮一盏，剩下那盏在闪。"},{"t":"c","id":"chengye","text":"那个通知，我看了三遍。三千八。"},{"t":"n","text":"他把手插进裤兜里。"},{"t":"c","id":"chengye","text":"我妈一个月挣不了三千八。"},{"t":"n","text":"你说那怎么办。"},{"t":"n","text":"他抬头看了一眼路灯。"},{"t":"c","id":"chengye","text":"不知道。先睡吧。明天还得上学。"}],"id":"chengye_03"},{"no":4,"title":"除了跑步","week":12,"bg":"court_day","cast":["chengye"],"steps":[{"t":"cast","list":["chengye"],"focus":"chengye"},{"t":"n","text":"操场边上停着一辆旧面包车。车门开着，里面放着一箱矿泉水。"},{"t":"n","text":"车身上有一道很长的划痕，从车头一直拉到车尾，用白漆补过，补得不太平。"},{"t":"n","text":"一个穿运动服的中年人站在跑道内侧，手里掐着秒表。"},{"t":"n","text":"他先没让跑。他让程野把鞋脱了。"},{"t":"n","text":"程野坐在跑道边，把鞋脱下来，翻过来，磕了磕。"},{"t":"n","text":"中年人蹲下去，捏了捏他的脚背，又捏了捏脚踝。"},{"t":"n","text":"「跑过几年？」"},{"t":"n","text":"「瞎跑。」"},{"t":"n","text":"「瞎跑能跑成这样。」"},{"t":"n","text":"他站起来，拍了拍手。"},{"t":"n","text":"「跑一个。」"},{"t":"n","text":"他让程野跑一个八百米。"},{"t":"n","text":"你坐在看台上，看他把校服外套脱了，扔在跑道边。"},{"t":"n","text":"起跑。第一圈他跟在另一个人后面，很稳。第二圈过弯，他往外道走了一步，开始加速。"},{"t":"n","text":"最后一百米他几乎是冲过去的。冲过线又跑了二十米才停。"},{"t":"n","text":"那个中年人低头看表，看了两遍，然后走过去说了几句话。"},{"t":"n","text":"程野一直在点头。"},{"t":"n","text":"面包车开走以后，他一个人在跑道上走，走了两圈，才上到看台来。"},{"t":"n","text":"他手里捏着一张纸条，是那个中年人留下的。上面写了电话号码，还有一行字：「想好了，打这个。」"},{"t":"n","text":"他把纸条对折，再对折，塞进校服口袋。"},{"t":"n","text":"「这个教练，」他说，「话不多。」"},{"t":"n","text":"他想了想。"},{"t":"c","id":"chengye","text":"跟我妈一样。"},{"t":"n","text":"他把手插进兜里，没有再说话。"},{"t":"n","text":"看台上的风大起来，他把外套的领子立起来，立了一半又放下去。"},{"t":"n","text":"他在你旁边坐下，两条腿伸出去，鞋底对着操场。"},{"t":"n","text":"他坐了很久没说话。风把他额头的汗吹干了，留下几道白印。"},{"t":"c","id":"chengye","text":"二分十一。"},{"t":"n","text":"他说。"},{"t":"c","id":"chengye","text":"他说我这样的，练两年能进省队。"},{"t":"n","text":"你说那你去啊。"},{"t":"n","text":"他把手撑在身后，仰起头看天。天是灰的，云一块一块压着。"},{"t":"c","id":"chengye","text":"我妈一个人。"},{"t":"n","text":"过了一会儿。"},{"t":"c","id":"chengye","text":"我除了跑，什么都不会。"},{"t":"n","text":"他说得很平，没有抱怨的意思。"},{"t":"c","id":"chengye","text":"真的。我数学三十八，英语二十几。语文作文写不满八百字，凑字数都凑不出来。"},{"t":"n","text":"他笑了一下。"},{"t":"c","id":"chengye","text":"我要是连跑都不跑了，我算什么。"},{"t":"n","text":"你说，你还会端盘子。"},{"t":"n","text":"他愣了一下，然后笑出声，笑得肩膀都在抖。"},{"t":"n","text":"笑完，他收了笑。"},{"t":"c","id":"chengye","text":"你别逗我。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"说「你去，饭馆我帮你看着」","hint":"这话很重 · 他会记住","eff":{"aff":5.0,"eq":2.0,"happy":2.0},"reply":[{"t":"n","text":"他说：「你看着？你会煮面吗。」"},{"t":"n","text":"你说不会。"},{"t":"n","text":"他笑了一下，这次是真的笑。"},{"t":"c","id":"chengye","text":"那你看着什么。"},{"t":"n","text":"你说，看着你妈，别让她一个人搬煤气罐。"},{"t":"n","text":"他脸上的笑慢慢收了。他低下头，用手背蹭了一下鼻子。"},{"t":"c","id":"chengye","text":"行。"}]},{"label":"B","text":"说「先别想那么远，把这学期考完」","hint":"把事拆小 · 好下手","eff":{"aff":3.0,"int":1.0,"stress":-1.0},"reply":[{"t":"n","text":"他想了想，说：「也是。」"},{"t":"n","text":"他从书包里掏出一本卷了边的练习册，翻到折角那一页。"},{"t":"c","id":"chengye","text":"这道题我做了三遍。三次都不一样。"},{"t":"n","text":"你说那说明你在进步。"},{"t":"c","id":"chengye","text":"说明我运气好。"}]},{"label":"C","text":"什么都不说，陪他坐着","hint":"不说话 · 他不需要","eff":{"aff":4.0,"happy":2.0,"stress":-1.0},"reply":[{"t":"n","text":"操场的灯亮了一盏。灯管坏了，亮两秒，灭一下。"},{"t":"n","text":"他忽然说：「你怎么不说话。」"},{"t":"n","text":"你说，不知道说什么。"},{"t":"n","text":"他想了一下。"},{"t":"c","id":"chengye","text":"行吧。你坐着就行。"}]}]},{"t":"n","text":"天黑得很快。教学楼那边的窗户一格一格亮起来。"},{"t":"n","text":"他站起来，拍了拍裤子上的灰。"},{"t":"c","id":"chengye","text":"要是我真去了，你会来看我跑吗。"},{"t":"n","text":"你说会。"},{"t":"n","text":"他点头，点得很用力。"},{"t":"c","id":"chengye","text":"第一排啊。别坐后面。"},{"t":"n","text":"他往看台下面走，边走边说。"},{"t":"c","id":"chengye","text":"我跑得快。一眨眼就到终点了。坐后面看不见。"}],"id":"chengye_04"}]},{"id":"ch1","title":"第一章 · 高中","scenes":[{"no":5,"title":"招新摊子","week":3,"bg":"court_day","cast":["jiangwan","chengye"],"steps":[{"t":"cast","list":["jiangwan","chengye"],"focus":"jiangwan"},{"t":"n","text":"开学第三周，操场边上摆了一排桌子。每个桌子后面坐着两个人，桌上立一块纸板。"},{"t":"n","text":"体育社的摊子在最边上，离厕所近，位置不好。"},{"t":"n","text":"桌子后面只有一个人。他坐在椅子上，两条腿伸出去，脚后跟磕着地。"},{"t":"n","text":"你走近了，他抬起头。"},{"t":"c","id":"chengye","text":"哎——"},{"t":"n","text":"他站起来，椅子往后一滑，差点倒。他伸手扶住，动作很快。"},{"t":"c","id":"chengye","text":"你真来了。"},{"t":"n","text":"纸板上写着「体育社」三个字，用的是黑色记号笔。「社」字写歪了，右边那一竖拖得很长。"},{"t":"n","text":"报名表压在桌角。格子是他自己用尺子画的，画得不太直。"},{"t":"n","text":"表格已经填了七个人。第一个是他自己的名字，「程野」两个字写得像两只站不稳的脚。"},{"t":"n","text":"桌上放着一个旧篮球，气不太足，按一下会陷进去。"},{"t":"c","id":"chengye","text":"填一个呗。"},{"t":"n","text":"你说你跑不快。"},{"t":"c","id":"chengye","text":"不用跑得快。有人负责跑，有人负责喊。"},{"t":"n","text":"他说完自己先笑了，露出那颗小虎牙。"},{"t":"n","text":"隔壁桌是文学社，江晚坐在那儿，正低头在本子上画什么。她抬头看了这边一眼，又低下去。"},{"t":"n","text":"过了一会儿，她又抬起头。"},{"t":"c","id":"jiangwan","text":"你们那张纸板，字写反了。"},{"t":"n","text":"程野低头看，把纸板转了个方向。"},{"t":"c","id":"chengye","text":"这样呢。"},{"t":"c","id":"jiangwan","text":"这样更反了。"},{"t":"n","text":"她说完就低下头，继续画。"},{"t":"n","text":"程野举着纸板，转来转去，最后索性拿起记号笔，把三个字重新写了一遍。"},{"t":"n","text":"体育老师从操场那头走过来，往桌上放了一箱水，说：「招够八个人，今年就留着。」"},{"t":"n","text":"程野说：「老师，已经七个了。」"},{"t":"n","text":"老师说：「还差一个。」"},{"t":"n","text":"老师走远以后，他压低声音：「去年招了六个，差点被撤。」"},{"t":"n","text":"他把那箱水搬到桌子底下，怕晒。"},{"t":"c","id":"chengye","text":"今年要是招满，场地就能留在下午。要不然只能排到早上六点。"},{"t":"n","text":"你说早上六点你也起得来。"},{"t":"n","text":"他抬头看你，眼睛亮了一下。"},{"t":"c","id":"chengye","text":"真的？"},{"t":"n","text":"你说真的。"},{"t":"n","text":"他从桌上拿起笔，在报名表边上写了一行小字。你凑过去看，写的是：「早六点，能来。」"},{"t":"n","text":"写完他自己看了看，说：「我先记上。你要是不来，我就划掉。」"},{"t":"n","text":"老师走远以后，他转回来，把笔递给你。"},{"t":"c","id":"chengye","text":"你看。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"报名","hint":"签个名 · 事就定了","eff":{"aff":5.0,"str":2.0,"happy":2.0},"reply":[{"t":"n","text":"你在第八个格子里写下自己的名字。"},{"t":"n","text":"他凑过来看，看了两秒。"},{"t":"c","id":"chengye","text":"字比我好看。"},{"t":"n","text":"他把报名表拿起来，抖了抖，对着太阳看了一遍，像在核对什么。"},{"t":"c","id":"chengye","text":"签了就是我的人了。"},{"t":"n","text":"说完他愣了一下，耳朵有点红，赶紧补了一句："},{"t":"c","id":"chengye","text":"开玩笑的。签了就是体育社的人了。"}]},{"label":"B","text":"只在旁边帮忙发传单","hint":"不填表 · 也算在一起","eff":{"aff":3.0,"eq":2.0,"happy":1.0},"reply":[{"t":"n","text":"你说，你就不填了，帮你发一会儿。"},{"t":"n","text":"他从桌下拖出一摞传单，一共没几张，边角被风吹得卷起来。"},{"t":"n","text":"你们站在主干道上发。大部分人接了走两步就扔掉。"},{"t":"n","text":"他弯腰把扔掉的那几张捡回来，抹平，重新塞进手里的那摞。"},{"t":"c","id":"chengye","text":"还能用。"},{"t":"n","text":"发到最后，还剩三张。他说不发了，留着。"}]},{"label":"C","text":"说你想专心学习","hint":"把话说清楚 · 不拖","eff":{"aff":-1.0,"int":2.0,"stress":-2.0},"reply":[{"t":"n","text":"你说，你想把时间放在学习上。"},{"t":"n","text":"他把笔收回去，点了点头。"},{"t":"c","id":"chengye","text":"行啊。那也没事。"},{"t":"n","text":"他把报名表压回桌角，用篮球压住，怕风吹走。"},{"t":"c","id":"chengye","text":"那你放学路过操场，给我打个招呼，总行吧。"},{"t":"n","text":"你说行。"}]}]},{"t":"n","text":"招新结束，他把没发完的传单叠成一摞，塞进书包侧兜。"},{"t":"n","text":"你问他留着干嘛。"},{"t":"n","text":"他把书包拉链拉上。"},{"t":"c","id":"chengye","text":"背面是白的。能打草稿。"},{"t":"n","text":"他背起书包，走了两步，又回头。"},{"t":"c","id":"chengye","text":"我也打不了几个草稿。"},{"t":"n","text":"他自己笑了。笑完，往操场那边跑了。"}],"id":"chengye_05"},{"no":6,"title":"四乘一百","week":8,"bg":"gym_day","cast":["chengye"],"steps":[{"t":"cast","list":["chengye"],"focus":"chengye"},{"t":"n","text":"市中学生运动会，借的是市体育场的场地。看台是水泥的，刷过一层绿漆，掉了不少。"},{"t":"n","text":"你们学校来了十几个人，坐在看台最下面一排。程野的号码布是 7 号。"},{"t":"n","text":"男子八百米决赛，一共十二个人。"},{"t":"n","text":"他站在起跑线上，弯下腰，两只手撑在膝盖上。你看不见他的脸。"},{"t":"n","text":"发令枪响。第一个两百米他跟在第四，不快。第二个两百米，他还是第四。"},{"t":"n","text":"看台上有人喊「程野加油」，喊得不太齐。"},{"t":"n","text":"还剩三百米的时候，他往外道走了一步。"},{"t":"n","text":"三百米、两百米、一百米。他一个一个超过去，超到第二个的时候，前面那个已经跑不动了。"},{"t":"n","text":"他冲线的时候，第二名还在十米外。"},{"t":"n","text":"计时牌上跳出一个数字：二分零六。"},{"t":"n","text":"他冲过线以后没有停，又往前走了几步，然后弯下腰。"},{"t":"n","text":"手撑在膝盖上，肩膀一起一伏。"},{"t":"n","text":"然后他吐了。"},{"t":"n","text":"没有人看见。看台上的人还在鼓掌，鼓完就散了。"},{"t":"n","text":"你从看台上翻下去，绕到跑道内侧。他蹲在跑道边的排水沟旁边，一只手撑着地。"},{"t":"n","text":"你把水递过去。他接过去，漱了口，吐掉。"},{"t":"n","text":"他抬起头，脸上全是汗，头发贴在额头上。"},{"t":"c","id":"chengye","text":"别跟别人说。"},{"t":"n","text":"你说好。"},{"t":"n","text":"他试着站起来，左腿伸了一下，又缩回去。"},{"t":"n","text":"你这才看见，他的左脚踝缠着绷带，绷带外面又套了一只护踝，护踝的魔术贴已经起毛了。"},{"t":"n","text":"他看见你在看，说：「昨天崴了一下。没事。」"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"帮他把绷带重新缠好","hint":"手上稳一点 · 他能感觉到","eff":{"aff":5.0,"str":1.0,"eq":1.0},"reply":[{"t":"n","text":"他把脚伸出来，脚踝内侧有一块青，边缘发黄。"},{"t":"n","text":"你把绷带拆开，重新绕。绕到第三圈的时候，他说「紧一点」。"},{"t":"n","text":"你说太紧不好。他说：「跑起来就不紧了。」"},{"t":"n","text":"你绕完，把魔术贴按牢。他站起来，在跑道上跳了两下。"},{"t":"c","id":"chengye","text":"行。稳。"}]},{"label":"B","text":"说「你这么跑，早晚要出事」","hint":"说句实话 · 不一定好听","eff":{"aff":2.0,"eq":3.0,"stress":-2.0},"reply":[{"t":"n","text":"他看着跑道，没说话。"},{"t":"n","text":"过了一会儿，他把水瓶盖拧上。"},{"t":"c","id":"chengye","text":"我知道。"},{"t":"n","text":"他抬了抬下巴，指向看台第二排。那里坐着两个穿运动外套的人，正在低头写字。"},{"t":"c","id":"chengye","text":"市里来看人的。今天跑不出来，就没了。"}]},{"label":"C","text":"装作没看见，扶他去医务室","hint":"不问 · 先把人扶走","eff":{"aff":4.0,"happy":2.0,"stress":-1.0},"reply":[{"t":"n","text":"你把他的胳膊架到自己肩上。他说不用，走了两步，还是没挣开。"},{"t":"n","text":"医务室在体育馆后面，一路都是水泥地。"},{"t":"n","text":"走到一半，他忽然说：「刚才那个第二名，他爸爸在看台上。」"},{"t":"n","text":"你说然后呢。"},{"t":"c","id":"chengye","text":"没什么。他跑得也挺好。"}]}]},{"t":"n","text":"颁奖的时候，他站在第三名的台子上——八百米按成绩排，他第一，但颁奖台按学校排，站错了位置，被叫下来重站。"},{"t":"n","text":"他站在最高的那一级，奖状卷成一个筒，拿在手里。"},{"t":"n","text":"他往看台这边看，找到你，把奖状举了一下。"},{"t":"n","text":"散场以后，他把奖状塞给你。"},{"t":"n","text":"回程的车上，一车人都在睡。他坐在最后一排靠窗，把腿伸直，搭在对面的座位上。"},{"t":"n","text":"车过收费站的时候，他忽然说：「市里那两个人，一个记了我的号码。」"},{"t":"n","text":"你说，记了就是有戏。"},{"t":"n","text":"他没接话，把脸转向窗户。玻璃上映出他的脸，还有窗外一直往后退的树。"},{"t":"n","text":"车到学校的时候，天已经黑了。他最后一个下车，把座位上的空水瓶捡起来，带下去扔了。"},{"t":"n","text":"你说那不是挺好。"},{"t":"n","text":"他摇头。"},{"t":"c","id":"chengye","text":"记号码的意思是，下次还来看。看不好，就再也不来了。"},{"t":"n","text":"你说你拿着干嘛。"},{"t":"c","id":"chengye","text":"帮我收着。"},{"t":"n","text":"他把运动包甩到肩上。"},{"t":"c","id":"chengye","text":"我怕我妈看见，又要说我耽误学习。"}],"id":"chengye_06"},{"no":7,"title":"冬天的小饭馆","week":12,"bg":"izakaya_night","cast":["chengye"],"steps":[{"t":"cast","list":["chengye"],"focus":"chengye"},{"t":"n","text":"十二月，饭馆里没有暖气，收银台旁边放了一个小太阳，橘红色的，只照得到一小块地。"},{"t":"n","text":"玻璃门上全是雾。有人进来，雾被推开一道缝，又慢慢合上。"},{"t":"n","text":"程野放学回来，书包往椅子上一放，围裙从墙上摘下来，套头，带子在背后一系。"},{"t":"n","text":"他系的还是死结。"},{"t":"n","text":"他妈妈在后厨，弯着腰从灶台下拿东西。弯到一半停住了，一只手撑在灶台上，缓了两秒，才直起来。"},{"t":"n","text":"他看见了，走过去，把他妈妈扶到一边，自己蹲下去。"},{"t":"n","text":"「我拿就行。」他说。"},{"t":"n","text":"后厨很窄，两个人转身都要侧着。"},{"t":"n","text":"外卖平台的打印机在收银台上响，吐出一张单子。他擦了下手，过去撕下来，扫了一眼，冲后厨喊：「一份牛肉面，不要香菜。」"},{"t":"n","text":"打印机又响。他站在那儿，等它吐完，把三张单子按顺序摆好。"},{"t":"n","text":"收银台的手机亮了一下。他低头看，看了很久。"},{"t":"n","text":"你凑过去。屏幕上是一条差评，两颗星，写着：「面太咸，老板态度还行，就是慢。」"},{"t":"n","text":"他在输入框里打字。打了一行，删了。又打一行，又删了。"},{"t":"n","text":"最后他发出去的是：「对不起，下次给您少放盐。」"},{"t":"n","text":"发完，他把手机扣在桌上。"},{"t":"c","id":"chengye","text":"你说，咸不咸我自己不知道吗。"},{"t":"n","text":"他说得很轻，像在跟自己说话。"},{"t":"n","text":"你没有接。"},{"t":"n","text":"他从收银台底下抽出一个本子，封皮是硬纸板，边角磨圆了。"},{"t":"n","text":"本子摊开，一页一页写着名字和数字。"},{"t":"n","text":"「王叔 46」「李奶奶 23」「三楼 118」「修车的张哥 30」。"},{"t":"n","text":"他念了一遍，从后往前念，念得很熟。"},{"t":"c","id":"chengye","text":"我妈不让催。"},{"t":"n","text":"他把本子合上，放回原处。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"帮他把外卖单子抄一遍","hint":"手上有活 · 时间过得快","eff":{"aff":4.0,"int":1.0,"happy":2.0},"reply":[{"t":"n","text":"你拿过一沓空白的单子，照着他念的顺序抄。"},{"t":"n","text":"写到第四张的时候，他凑过来看，说：「你这个字，写单子上可惜了。」"},{"t":"n","text":"你说那你写。"},{"t":"n","text":"他把笔接过去，写了一个「面」字，写完自己看了看，说：「算了，还是你写。」"},{"t":"n","text":"两个人一个念一个写。写到一半，打印机又响了，他去看，回来的时候手里多了一瓶汽水，放在你手边，没说话。"}]},{"label":"B","text":"陪他去给赊账的人送面","hint":"走一趟巷子 · 认识这条街","eff":{"aff":6.0,"eq":2.0,"familyRel":1.0},"reply":[{"t":"n","text":"最后一单要送到三楼。他拎着保温袋，你跟着。"},{"t":"n","text":"楼道没有灯，他一边走一边用手机照，光晃在墙上。"},{"t":"n","text":"开门的是个老太太，穿着棉袄，屋里电视开得很响。"},{"t":"n","text":"「又麻烦你。」她说。"},{"t":"n","text":"「不麻烦。」他把面放在桌上，顺手把电视声音调小了一点。"},{"t":"n","text":"老太太从口袋里摸出几张钱，数了半天。他说：「不着急，下个月给。」"},{"t":"n","text":"下楼的时候，他走在前面，手插在兜里。"},{"t":"c","id":"chengye","text":"我妈说，谁都有难的时候。"},{"t":"n","text":"他顿了一下。"},{"t":"c","id":"chengye","text":"我爸走那年，这条巷子的人天天来吃面。一碗面，坐一下午。"}]},{"label":"C","text":"坐在角落写作业，等他忙完","hint":"各做各的 · 也是一种陪","eff":{"aff":3.0,"int":1.0,"happy":2.0},"reply":[{"t":"n","text":"你挑了最里面那张桌子，把作业摊开。"},{"t":"n","text":"他一会儿端菜，一会儿收碗，每次经过都要瞥一眼你的卷子。"},{"t":"n","text":"第三次经过的时候，他停下来说：「这道题，是不是要先算括号里的。」"},{"t":"n","text":"你抬头看他。他立刻摆手。"},{"t":"c","id":"chengye","text":"我瞎说的。你别听我的。"},{"t":"n","text":"你按他说的算了，答案是对的。"},{"t":"n","text":"他站在那儿，愣了一下，然后笑起来，笑得特别大声。"},{"t":"c","id":"chengye","text":"你看！我就说我不笨！"}]}]},{"t":"n","text":"九点半打烊。他把卷帘门拉下来一半，留一条缝透气。"},{"t":"n","text":"他煮了两碗面，一碗给你。面上卧了一个蛋。"},{"t":"n","text":"他吃得很快，吃完把碗一推，坐在那儿算账。你看见他在纸上写：房租三千，水电四百，进货一千二。"},{"t":"n","text":"写到最后，他停住了。"},{"t":"c","id":"chengye","text":"我这学期学费八千。"},{"t":"n","text":"他把笔帽盖上，盖上又拔下来。"},{"t":"c","id":"chengye","text":"我有时候想，我要是不上学了，是不是就好了。"},{"t":"n","text":"你说别胡说。"},{"t":"n","text":"他抬起头，笑了一下。"},{"t":"c","id":"chengye","text":"我就想想。"}],"id":"chengye_07"},{"no":8,"title":"单招","week":22,"bg":"corridor_night","cast":["chengye"],"steps":[{"t":"cast","list":["chengye"],"focus":"chengye"},{"t":"n","text":"高三上学期，走廊里贴了单招的简章。一张 A4 纸，印着体校的名字和一张模糊的操场照片。"},{"t":"n","text":"程野站在那张纸前面，站了很久。下课的人流从他两边过去。"},{"t":"n","text":"班主任把他叫进办公室，说了二十分钟。出来的时候，他手里多了一张报名表。"},{"t":"n","text":"他走到走廊尽头的窗边，把表摊在窗台上，一个字一个字地看。"},{"t":"n","text":"你走过去。他没抬头。"},{"t":"c","id":"chengye","text":"文化课要一百八。"},{"t":"n","text":"他把手指按在那一行字上。"},{"t":"c","id":"chengye","text":"我现在一百六。"},{"t":"n","text":"你说那就补。"},{"t":"n","text":"他把手指收回去，插进校服兜里。"},{"t":"c","id":"chengye","text":"我补了两年了。"},{"t":"n","text":"窗外的操场上有人在跑步，跑得很慢，一圈一圈。"},{"t":"c","id":"chengye","text":"但我不补，就真的只能跑了。"},{"t":"n","text":"上课铃响了。他没动。"},{"t":"n","text":"下午最后一节课，他妈妈来了。穿着那件洗得发白的棉袄，站在办公室门口，手在衣角上搓。"},{"t":"n","text":"门没关严。声音不大，但走廊很静。"},{"t":"n","text":"「老师，他要是去练体育，以后怎么办？」"},{"t":"n","text":"班主任说了什么，听不清。"},{"t":"n","text":"「跑不动了怎么办？」他妈妈说，「他才十七。」"},{"t":"n","text":"程野站在拐角，背靠着墙，没出去。"},{"t":"n","text":"他妈妈的声音又低下去，说了很长一段。最后一句很清楚："},{"t":"n","text":"「他爸当年也说自己有数。」"},{"t":"n","text":"程野的喉结动了一下。"},{"t":"n","text":"办公室的门开了一条缝。他妈妈的影子从缝里落出来，长长的一条，铺在走廊的地上。"},{"t":"n","text":"程野贴着墙，往阴影里退了半步。"},{"t":"n","text":"他抬起手，想敲门。手停在半空，又放下。"},{"t":"n","text":"走廊尽头的窗户开着，风把公示栏上的纸吹得哗哗响。是三张成绩表。"},{"t":"n","text":"他看了一眼，把头转开。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"走过去，站到他旁边","hint":"不说话 · 只是站着","eff":{"aff":5.0,"happy":3.0,"stress":-2.0},"reply":[{"t":"n","text":"你走过去，站到他旁边，也背靠着墙。"},{"t":"n","text":"他侧头看了你一眼，没说话。"},{"t":"n","text":"办公室里，他妈妈还在说。说到一半，她抬起头，看见门口站着的两个人。"},{"t":"n","text":"她停住了。"},{"t":"n","text":"程野直起身，走过去。"},{"t":"c","id":"chengye","text":"妈，我在这儿。"},{"t":"n","text":"他说得很稳。"},{"t":"c","id":"chengye","text":"我练体育，不是不学。单招也要考文化课。"},{"t":"n","text":"他妈妈看着他。"},{"t":"n","text":"「你爸当年也这么说。」"},{"t":"n","text":"程野没有低头。"},{"t":"c","id":"chengye","text":"我不是我爸。"},{"t":"n","text":"走廊里安静了很久。他妈妈从包里拿出一个塑料袋，塞到他手里。"},{"t":"n","text":"「晚上回来吃饭。」她说，转身下楼了。"}]},{"label":"B","text":"替他跟他妈说一句","hint":"话到嘴边 · 又觉得不该","eff":{"aff":2.0,"eq":2.0,"happy":-1.0},"reply":[{"t":"n","text":"你往前走了半步，想说什么。"},{"t":"n","text":"他伸手拦了一下，很轻。"},{"t":"c","id":"chengye","text":"我来。"},{"t":"n","text":"他走出去，站在办公室门口，叫了一声「妈」。"},{"t":"n","text":"他妈妈回过头。两个人隔着半个走廊。"},{"t":"n","text":"他张了张嘴，最后说的是：「你先回家。这儿冷。」"},{"t":"n","text":"他妈妈看了他两秒，点了点头。"}]},{"label":"C","text":"拉他走开，去操场","hint":"先离开 · 再说别的","eff":{"aff":4.0,"str":1.0,"stress":-3.0},"reply":[{"t":"n","text":"你拉了一下他的袖子。他跟着你走了。"},{"t":"n","text":"操场上没人。煤渣跑道冻硬了，踩上去咯吱响。"},{"t":"n","text":"他走到跑道边上，蹲下来，抓了一把冻硬的土，又松开。"},{"t":"c","id":"chengye","text":"我不是气她。"},{"t":"n","text":"他站起来，拍掉手上的土。"},{"t":"c","id":"chengye","text":"我是气我自己。她说的那些，我一条都答不上来。"}]}]},{"t":"n","text":"晚上，你收到他的消息。"},{"t":"n","text":"第一条：「我妈给我煮了排骨。」"},{"t":"n","text":"过了两分钟，第二条：「她说，跑不动了就回来。」"},{"t":"n","text":"又过了很久，第三条只有三个字：「我不回。」"},{"t":"n","text":"第二天早自习，他坐在座位上，报名表已经填好了，摊在桌上，边角被手汗磨得发软。"},{"t":"n","text":"他把表推给你看。监护人签字那一栏，空着。"},{"t":"n","text":"签字栏上有一道铅笔的印子。擦了又写，写了又擦，纸都起了毛。"},{"t":"n","text":"他伸手把表收回去，折成三折，夹进课本里。"},{"t":"n","text":"他说：「等我妈签。」"},{"t":"n","text":"他说这话的时候，语气很笃定，像在说一件已经发生的事。"}],"id":"chengye_08"},{"no":9,"title":"毕业日","week":24,"bg":"sakura_path","cast":["chengye"],"steps":[{"t":"cast","list":["chengye"],"focus":"chengye"},{"t":"n","text":"毕业典礼在礼堂，开了一个半小时。校长讲话，学生代表讲话，中间有人偷偷在下面打牌。"},{"t":"n","text":"散场以后，所有人都挤在校门口。有人在哭，有人在拍照，有人在等家长的车。"},{"t":"n","text":"程野的校服背后签满了名字。前面也签满了。袖子上还有两个。"},{"t":"n","text":"他从人群里挤出来，手里拿着一个牛皮纸信封，信封已经软了，折了好几道。"},{"t":"n","text":"他把信封举起来，冲你晃了晃。"},{"t":"c","id":"chengye","text":"录了。"},{"t":"n","text":"省体校，运动训练专业。三年制。"},{"t":"n","text":"你说恭喜。他把信封塞回裤兜，动作很随意，但塞了两次才塞进去。"},{"t":"n","text":"他从书包里掏出一支马克笔，塞到你手里，转过身去，把背对着你。"},{"t":"c","id":"chengye","text":"签一个。签大点。"},{"t":"n","text":"你在他背上找了块空地。他校服背后已经没什么空地了。"},{"t":"n","text":"你签完，他扭头想看，看不见，就把校服脱下来，摊在手上看。"},{"t":"c","id":"chengye","text":"这衣服我不洗了。"},{"t":"n","text":"他妈签字那天，是在饭馆的收银台上签的。签完，她把笔放下，说了一句「跑不动了就回来」。"},{"t":"n","text":"程野说，他那天晚上把这句话想了一夜，最后想明白了：她不是不同意，她是怕。"},{"t":"n","text":"他从书包侧兜里掏出一张号码布。白底黑字，7 号，边角被别针扎出了四个洞。"},{"t":"n","text":"号码布洗过，字有点淡了。他用手指把边角抹平，抹了两下。"},{"t":"n","text":"「这四个孔，」他说，「是我自己别的。扎了四次才别正。」"},{"t":"n","text":"「后来我就学会了。四个角各别一个，跑起来不晃。」"},{"t":"n","text":"他把号码布翻过来，看了看背面。什么也没有。"},{"t":"c","id":"chengye","text":"这个你拿着。我柜子里还有一堆。"},{"t":"n","text":"你说这算什么。"},{"t":"n","text":"他把号码布拍在你手心里。"},{"t":"c","id":"chengye","text":"算我押在你这儿。"},{"t":"n","text":"校门口的风把地上的彩带吹起来，贴着地面滚。"},{"t":"n","text":"他忽然想起什么，从兜里摸出手机，翻了两下，递给你看。"},{"t":"n","text":"是一张照片：体校的操场，跑道是红色的，看台只有五排。"},{"t":"c","id":"chengye","text":"他们那儿跑道是红的。比咱们学校的好跑。"},{"t":"n","text":"他把手机收回去。"},{"t":"c","id":"chengye","text":"九月开学。以后有比赛，我给你寄票。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"说「我一定去」","hint":"答应得干脆 · 他会当真","eff":{"aff":5.0,"happy":3.0,"stress":-1.0},"reply":[{"t":"n","text":"他点头，点得很快。"},{"t":"c","id":"chengye","text":"那你可得坐第一排。"},{"t":"n","text":"他说完，好像觉得这话说得太认真了，挠了挠头。"},{"t":"c","id":"chengye","text":"我跑得快，一眨眼就到终点了。坐后面看不见。"},{"t":"n","text":"你说你知道了。他说：「你上次也这么说。」"}]},{"label":"B","text":"说「你先跑到能寄票再说」","hint":"激他一句 · 他会笑","eff":{"aff":3.0,"eq":1.0,"happy":3.0},"reply":[{"t":"n","text":"他愣了一下，然后笑出声，笑得弯下腰。"},{"t":"c","id":"chengye","text":"行。你等着。"},{"t":"n","text":"他把校服往肩上一搭，另一只手在空气里划了一下，像在冲线。"},{"t":"c","id":"chengye","text":"明年这个时候，票就到你手上了。"},{"t":"n","text":"他说得很大声，旁边两个同学回头看。"}]},{"label":"C","text":"说「到了那边，别一个人硬扛」","hint":"把担心说出来 · 不藏","eff":{"aff":6.0,"stress":-2.0,"happy":2.0},"reply":[{"t":"n","text":"他脸上的笑收了收，但没有全收。"},{"t":"n","text":"他把校服抱在怀里，低头看了一会儿那些签名。"},{"t":"c","id":"chengye","text":"我尽量。"},{"t":"n","text":"他抬起头。"},{"t":"c","id":"chengye","text":"但你也知道我这人。跑起来就什么都不想了。"}]}]},{"t":"n","text":"他家在巷子里，坐 12 路公交。站台上只有你们两个人。"},{"t":"n","text":"车来了。他把校服和信封一起抱在怀里，上了车，站在车门边。"},{"t":"n","text":"车门要关的时候，他忽然冲你喊了一句。"},{"t":"n","text":"发动机的声音很大，你只听见中间那个字是「我」。"},{"t":"n","text":"车开走了。尾灯在巷口拐了一下，就不见了。"},{"t":"n","text":"后来你猜了很多年。猜他是说「等我」，猜他是说「我会去」，猜他是说「我妈那边，我搞定」。"},{"t":"n","text":"你一直没有问。他也没有再提。"}],"id":"chengye_09"}]},{"id":"ch2","title":"第二章 · 大学","scenes":[{"no":10,"title":"两个城市","week":25,"bg":"bedroom_night","cast":["chengye"],"steps":[{"t":"cast","list":["chengye"],"focus":"chengye"},{"t":"n","text":"九月的宿舍还没有热起来。熄灯以后，你躺在床上，手机屏幕朝上，亮得刺眼。"},{"t":"n","text":"他发来一条语音，五十八秒。"},{"t":"n","text":"你点开。背景是操场，有人在喊号子，风很大。"},{"t":"n","text":"「今天第一天训练，教练让我跑了一千二。我跑完腿都是软的。这边食堂的饭不行，没有我妈做的好吃。哎对了，我们宿舍六个人，五个都是练田径的，有一个练铅球，胳膊比我大腿粗。」"},{"t":"n","text":"中间有十几秒只有风的声音。"},{"t":"n","text":"「你在那边怎么样。有人欺负你就说。」"},{"t":"n","text":"语音结束。"},{"t":"n","text":"你回了一条文字。他很快回了一个「哦」。"},{"t":"n","text":"过了两分钟，又发来一条：「我不会打字。你多发点。」"},{"t":"n","text":"十月，他发来一张照片：体校宿舍的墙，贴着一张手写的训练计划表。"},{"t":"n","text":"字还是那么丑。「六点起」「八组四百」「晚上拉伸」。"},{"t":"n","text":"表格最下面画了一个小人，只有一个圆脑袋两条腿，旁边写着：「跑」。"},{"t":"n","text":"十一月，他第一次参加省里的比赛。"},{"t":"n","text":"比赛前一周，他发来一张照片：训练场边的长椅，上面放着一双跑鞋，鞋跟磨平了。"},{"t":"n","text":"配的字是：「新的舍不得穿。旧的还能跑。」"},{"t":"n","text":"第二天又发来一张：膝盖上贴着一块胶布，胶布边缘翘起来。"},{"t":"n","text":"「昨天摔了一跤。没事，皮外伤。」"},{"t":"n","text":"成绩出来那天，他发了两个字：「二分零三。」"},{"t":"n","text":"你说，很好啊。"},{"t":"n","text":"他隔了很久才回。"},{"t":"n","text":"「教练说，省队要一分五十八。」"},{"t":"n","text":"那天晚上十一点，他打电话过来。"},{"t":"n","text":"接通以后，他先没说话。你听见他那边有风吹过话筒的声音。"},{"t":"c","id":"chengye","text":"我今天跑完了，一个人在场边坐着。"},{"t":"n","text":"他停了一下。"},{"t":"c","id":"chengye","text":"突然想给你打电话。"},{"t":"n","text":"你说，那你怎么不说话。"},{"t":"n","text":"他笑了一下，很短。"},{"t":"c","id":"chengye","text":"不知道说什么。"},{"t":"n","text":"又安静了几秒。"},{"t":"c","id":"chengye","text":"没事。挂了。"},{"t":"n","text":"挂了以后，他发来一条消息：「刚才风大。」"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"说「下次比赛我去看你」","hint":"把话说到具体","eff":{"aff":5.0,"happy":4.0,"stress":-1.0,"fin":-2.0},"reply":[{"t":"n","text":"他回得很快：「真的？」"},{"t":"n","text":"你说真的。"},{"t":"n","text":"他发了三个感叹号，又发了一条：「那我给你留第一排。这边看台第一排离跑道只有三米。」"},{"t":"n","text":"过了一会儿，他发来一张票的照片，票面上印着「观众席 · 一区 · 一排」。"},{"t":"n","text":"「先给你看看。真票等我拿到再寄。」"}]},{"label":"B","text":"说「你先睡吧，明天还要练」","hint":"不追问 · 让他休息","eff":{"aff":2.0,"happy":1.0,"stress":-2.0},"reply":[{"t":"n","text":"他回了一个「好」。"},{"t":"n","text":"你放下手机，屏幕暗了。"},{"t":"n","text":"过了大概十分钟，屏幕又亮了一下。"},{"t":"n","text":"他发来一句：「你也早点睡。别老熬夜。」"},{"t":"n","text":"就这一句。没有别的。"}]},{"label":"C","text":"问他「你们那边冬天冷不冷」","hint":"从天气说起 · 慢慢聊","eff":{"aff":4.0,"eq":2.0,"happy":3.0},"reply":[{"t":"n","text":"他回了一大段，还发了一张照片：宿舍窗外的树，叶子掉了一半。"},{"t":"n","text":"「冷。这边风是从操场那头过来的，一点挡的都没有。我们早上六点出操，跑完手都僵了，握不住筷子。」"},{"t":"n","text":"然后又发一条。"},{"t":"n","text":"「不过跑起来就不冷了。跑起来的时候，身上是热的。」"},{"t":"n","text":"最后一条是一个很短的句子，短到像是随手打的："},{"t":"n","text":"「你问这个，我挺高兴的。」"}]}]},{"t":"n","text":"寒假前，你收到一张明信片。正面是体校的操场，红色的跑道，五排看台，天很蓝。"},{"t":"n","text":"他是寄到宿舍的。寄之前打过一次电话，问你楼号和房间号，问得很细。"},{"t":"n","text":"你说寄学校收发室就行。他说：「寄学校容易丢。我写了一晚上。」"},{"t":"n","text":"背面是他的字，写得很大，占满了整张卡。"},{"t":"n","text":"「这里的跑道是红的。比咱们学校的好跑。」"},{"t":"n","text":"下面还有一行，小得多，挤在最底下："},{"t":"n","text":"「你什么时候来。」"}],"id":"chengye_10"},{"no":11,"title":"雨天的球场","week":30,"bg":"court_rain","cast":["chengye"],"steps":[{"t":"cast","list":["chengye"],"focus":"chengye"},{"t":"n","text":"比赛在体校本馆，是场交流赛。对手是邻省的一支青年队。"},{"t":"n","text":"比分一直咬着。最后两分钟，程野被换上场。"},{"t":"n","text":"他跑动不多。你坐在第一排，能看见他每次起跳落地时，左脚都轻轻收一下。"},{"t":"n","text":"终场哨响，输了六分。"},{"t":"n","text":"观众散得很快。灯关了一半，馆里暗下来。"},{"t":"n","text":"他没有跟队里一起走。他抱着一个球，走到场地另一头，开始投。"},{"t":"n","text":"一个，两个，三个。球砸在篮板上，弹回来，他走过去捡，再投。"},{"t":"n","text":"你从看台上下来，走到场边。场边放着你带来的伞和一条毛巾——毛巾是从看台上捡的，不知道是谁落下的。"},{"t":"n","text":"外面开始下雨。雨点打在体育馆的铁皮顶上，很响。"},{"t":"n","text":"他没有走。他把球衣的下摆塞进裤腰里，又投了一个。"},{"t":"n","text":"球在篮筐上弹了一下，没进。滚到墙角。"},{"t":"n","text":"他去捡球。走路的时候，左脚有点跛。"},{"t":"n","text":"你这才看清，他的左脚踝肿了，护踝摘了，脚踝内侧鼓起来一块。"},{"t":"n","text":"他把球捡回来，转过来，看见了你。"},{"t":"n","text":"他抹了一把脸上的水。分不清是雨还是汗。"},{"t":"c","id":"chengye","text":"你怎么来了。快回去，别淋着。"},{"t":"n","text":"他说完，没等你回答，又投了一个。球砸在篮筐前沿，弹得很远。"},{"t":"n","text":"球架底下响了一声。是他的手机。"},{"t":"n","text":"屏幕亮着，上面两个字：「妈」。"},{"t":"n","text":"他看了一眼，没有接。屏幕亮了很久，灭了。"},{"t":"n","text":"他把球捡回来，抱在怀里，站在三分线外，没有投。"},{"t":"n","text":"雨从馆门口飘进来，把他脚边的地面打湿了一小片。"},{"t":"c","id":"chengye","text":"家里那个店，可能要盘出去。"},{"t":"n","text":"他说得很平。"},{"t":"c","id":"chengye","text":"我妈腰不好。上个月去医院，医生说要手术。她一直拖着。"},{"t":"n","text":"他把球往地上一按，球弹起来，接住。"},{"t":"c","id":"chengye","text":"我这个月有场比赛。赢了有奖金。不多，五千。"},{"t":"n","text":"他笑了一下。"},{"t":"c","id":"chengye","text":"五千。够她做一个检查。"},{"t":"n","text":"他抬起头，看着篮筐。"},{"t":"c","id":"chengye","text":"所以我不能停。"},{"t":"n","text":"他把球投出去。进了。球从网里落下来，在地上弹了三下。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"走进雨里，陪他投完最后一个球","hint":"陪他淋一次雨 · 体魄 ↑","eff":{"aff":6.0,"str":2.0,"stress":2.0,"happy":2.0},"reply":[{"t":"n","text":"你把伞放在场边，走进去。地是湿的，鞋底打滑。"},{"t":"n","text":"他愣了一下。"},{"t":"c","id":"chengye","text":"你干嘛！回去！"},{"t":"n","text":"你说，投完最后一个。"},{"t":"n","text":"他看了你两秒，把球扔给你。"},{"t":"n","text":"你投了一个。三不沾。"},{"t":"n","text":"他笑得很大声，笑声在空馆里荡开。"},{"t":"n","text":"他接过球，站在罚球线上，深呼吸，投出去。"},{"t":"n","text":"球在篮筐上转了两圈。进了。"},{"t":"n","text":"他愣住，然后笑起来，冲你伸出手。"},{"t":"c","id":"chengye","text":"赢了。"},{"t":"n","text":"你和他击掌。他的手很凉。"},{"t":"n","text":"他握着你的手，没有马上松。"},{"t":"n","text":"然后他松开，低头说了一句：「其实输了。」"},{"t":"n","text":"你说你知道。"}]},{"label":"B","text":"把毛巾扔给他，拉他去吃饭","hint":"先吃顿热的 · 心情 ↑","eff":{"aff":4.0,"happy":3.0,"eq":1.0},"reply":[{"t":"n","text":"毛巾扔过去，正好罩在他头上。他扯下来，头发乱着。"},{"t":"n","text":"你说，先吃饭。吃完再投。"},{"t":"n","text":"他本来想说什么，肚子先响了一声。他低头看了看自己的肚子。"},{"t":"c","id":"chengye","text":"行吧。"},{"t":"n","text":"球馆外面有一家面馆，还开着。两碗牛肉面，他一碗，你一碗。"},{"t":"n","text":"他饿坏了，吃了两碗，还把汤喝了。"},{"t":"n","text":"吃到最后，他手机响了。他看了屏幕一眼，接了。"},{"t":"c","id":"chengye","text":"妈。嗯。吃了。"},{"t":"n","text":"他一边说一边用筷子拨碗里剩下的葱花。"},{"t":"c","id":"chengye","text":"吃了两大碗。真的。你不信问他。"},{"t":"n","text":"他把手机往你这边递了一下，又收回去。"},{"t":"n","text":"挂了电话，他低头喝汤，很久没抬头。"},{"t":"n","text":"结账的时候他抢着付。"},{"t":"c","id":"chengye","text":"下次我请。"},{"t":"n","text":"你说明天就明天。"},{"t":"n","text":"他愣了一下，笑了。"},{"t":"c","id":"chengye","text":"行啊。你倒是会顺杆爬。"}]},{"label":"C","text":"劝他别练了，会受伤","hint":"说句实话 · 他会记住","eff":{"aff":2.0,"eq":2.0,"stress":-2.0},"reply":[{"t":"n","text":"你说，你这个脚，再练下去就废了。"},{"t":"n","text":"他没有立刻回答。他看着篮筐，看了很久。"},{"t":"c","id":"chengye","text":"我知道。"},{"t":"n","text":"他把球在手里转了一圈。"},{"t":"c","id":"chengye","text":"可我不练，就什么都没有了。"},{"t":"n","text":"他停了一下。"},{"t":"c","id":"chengye","text":"我家那个饭馆，你知道吧。我妈一个人撑了十年。"},{"t":"n","text":"他抬起头，看着体育馆顶上的灯。"},{"t":"c","id":"chengye","text":"我要是连球都打不好……"},{"t":"n","text":"他没说完。他把球扔向篮筐。"},{"t":"n","text":"球没进。砸在篮板上，弹回来，滚到他脚边。"},{"t":"n","text":"他站着没动。"}]}]},{"t":"n","text":"雨停的时候已经十点半。他把球放回球筐，关灯，锁门。"},{"t":"n","text":"你们走到校门口。他的手机又亮了。"},{"t":"n","text":"这一次他接了。"},{"t":"c","id":"chengye","text":"妈。……嗯，我知道。……我想想办法。"},{"t":"n","text":"他一边说一边往前走，走了十几步，停下来。"},{"t":"c","id":"chengye","text":"你别卖。等我回来。"},{"t":"n","text":"挂了电话，他站在路灯底下，仰起头，看了很久。"},{"t":"n","text":"你说，走吧。"},{"t":"n","text":"他「嗯」了一声，跟上来。"},{"t":"n","text":"走了很远，他忽然说："},{"t":"c","id":"chengye","text":"你今天要是不来，我可能就坐那儿坐一宿。"},{"t":"block","when":"flag1","steps":[{"t":"n","text":"他弯腰把球捡起来，走到场边，拿起那条毛巾，擦了一把脸。"},{"t":"n","text":"然后他解下右手腕上的护腕。"},{"t":"n","text":"黑色的，边已经起毛。他抓起你的手，把护腕套上去。"},{"t":"n","text":"太大了，松松地挂着。他捏着你的手腕，把魔术贴按了一下，按到一个最紧的档，还是松。"},{"t":"c","id":"chengye","text":"下次比赛，坐第一排。"},{"t":"n","text":"他说完就转身跑回雨里，捡起球，又投了一个。"},{"t":"n","text":"你低头看那个护腕。"},{"t":"n","text":"内侧用圆珠笔写了一行小字，被汗浸得有点花。"},{"t":"n","text":"两个字：「别怕。」"}]},{"t":"block","when":"low","steps":[{"t":"n","text":"他把球抱在怀里，站了一会儿。"},{"t":"c","id":"chengye","text":"你回去吧。雨大。"},{"t":"n","text":"他把毛巾拿起来，走回场边，叠了两下，放在你手里。"},{"t":"n","text":"你走到馆门口，回头看了一眼。他还在投。"},{"t":"n","text":"第二天，他发来一条消息：「昨天谢谢你。」"},{"t":"n","text":"没有下一句。"}]}],"id":"chengye_11"},{"no":12,"title":"第一次首发","week":33,"bg":"gym_day","cast":["chengye"],"steps":[{"t":"cast","list":["chengye"],"focus":"chengye"},{"t":"n","text":"体校的田径场比照片上旧。红色跑道晒得发白，看台只有五排，水泥台阶上刷着区号。"},{"t":"n","text":"你到得早。看台上没什么人，一个老头在扫地上的落叶，扫帚刮着水泥地。"},{"t":"n","text":"你按票上的号找位置。一区一排。离跑道只有三米，近得能看见起跑器上的锈。"},{"t":"n","text":"暖场音乐从喇叭里出来，有点破音。"},{"t":"n","text":"队员从通道里出来的时候，你一眼就看见了他。7 号。"},{"t":"n","text":"他走路的时候左脚落地比右脚轻一点，不明显。护踝换成了新的，白色。"},{"t":"n","text":"他在跑道边放下包，蹲下来系鞋带。系完站起来，往看台这边扫了一眼。"},{"t":"n","text":"看见你，他抬手比了个手势，意思是「就那儿，别动」。"},{"t":"n","text":"然后他转身往洗手间走。过了三分钟又出来，脸上还挂着水。"},{"t":"n","text":"过了一会儿，他又去了一趟。"},{"t":"n","text":"第三次出来的时候，他在通道口站了一下，深吸一口气，才走进场地。"},{"t":"n","text":"八百米，十二个人，两圈。"},{"t":"n","text":"发令枪响。他起跑不快，落在第六。第一个四百米，他一直贴着内道，位置很稳。"},{"t":"n","text":"第二个四百米，前面的人开始拉开。他一点一点往前挪，挪到第四。"},{"t":"n","text":"最后一个弯道，他想从内道切过去，被前面的人挡了一下，只能绕到外道。"},{"t":"n","text":"外道多跑了六七米。"},{"t":"n","text":"最后一百米，他追上了第三，追不上第二。"},{"t":"n","text":"冲线。"},{"t":"n","text":"他没有立刻停下，又往前跑了十几米，才慢慢减速，双手撑着膝盖。"},{"t":"n","text":"然后他直起身，抬头往看台上看。"},{"t":"n","text":"你在第一排，举了举手。"},{"t":"n","text":"他看见了，抬了抬下巴。就这一个动作，没有笑。"},{"t":"n","text":"赛后，队员们在场地边拉伸。教练拿着一个夹子，一个一个说话。"},{"t":"n","text":"说到程野的时候，教练说得比较久。他一直在点头。"},{"t":"n","text":"后来他走过来，隔着栏杆。"},{"t":"c","id":"chengye","text":"第三。"},{"t":"n","text":"他说。"},{"t":"c","id":"chengye","text":"名单没上。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"在出口等他，什么都不说，先递水","hint":"先给他一口水","eff":{"aff":5.0,"happy":3.0,"stress":-2.0},"reply":[{"t":"n","text":"他从通道出来的时候，头发还是湿的，包背在一边肩上。"},{"t":"n","text":"你把水递过去。他接过去，拧开，喝了一半。"},{"t":"n","text":"两个人站在通道口，谁也没说话。有人从旁边过去，撞了一下他的包。"},{"t":"n","text":"他把包挪了挪。"},{"t":"c","id":"chengye","text":"走吧。食堂还开着。"}]},{"label":"B","text":"说「你今天最后那圈，比上次快了」","hint":"说出你看见的东西","eff":{"aff":6.0,"eq":2.0,"happy":3.0},"reply":[{"t":"n","text":"他愣了一下。"},{"t":"c","id":"chengye","text":"你怎么知道。"},{"t":"n","text":"你说，你记了。上次是二分零三，这次是二分零一。"},{"t":"n","text":"他站在那儿，看了你很久，久到有点不自在。"},{"t":"n","text":"他把包换到另一边肩上。"},{"t":"c","id":"chengye","text":"两秒。"},{"t":"n","text":"他低头笑了一下，笑得有点不好意思。"},{"t":"c","id":"chengye","text":"两秒。我练了四个月。"},{"t":"n","text":"他抬起头。"},{"t":"c","id":"chengye","text":"不过两秒也是快。"}]},{"label":"C","text":"说「要不别练了」","hint":"这话说出口 · 他会安静","eff":{"aff":-2.0,"stress":-3.0,"eq":1.0},"reply":[{"t":"n","text":"他脸上的表情没有变。"},{"t":"n","text":"他把包带往肩上提了提。"},{"t":"c","id":"chengye","text":"你也这么说。"},{"t":"n","text":"他说完，往前走。走了几步，又停下。"},{"t":"c","id":"chengye","text":"我妈说，教练说，你也说。"},{"t":"n","text":"他回过头。"},{"t":"c","id":"chengye","text":"那我说什么。"},{"t":"n","text":"你没有回答。他也没有等你回答。"}]}]},{"t":"n","text":"食堂在宿舍楼一层。他刷了卡，两荤一素，米饭压得很实。"},{"t":"n","text":"他把盘子端过来，往你那边推了推。"},{"t":"c","id":"chengye","text":"我们这儿的红烧肉，比外面的大。"},{"t":"n","text":"他夹了一块放到你碗里，自己也夹了一块，嚼了两下，说：「今天烧得有点老。」"},{"t":"n","text":"吃到一半，他从裤兜里掏出一个小本子。巴掌大，封面是塑料的，已经磨花。"},{"t":"n","text":"他翻到其中一页，用笔写了一个字：「三」。"},{"t":"n","text":"你凑过去看。那一页上写满了「三」。有的写得工整，有的写得很潦草。"},{"t":"n","text":"往前翻，还有「四」「五」「六」。"},{"t":"c","id":"chengye","text":"记着。"},{"t":"n","text":"他把本子合上，塞回兜里，继续吃饭。"},{"t":"c","id":"chengye","text":"哪天写满了，就不写了。"}],"id":"chengye_12"},{"no":13,"title":"抽水","week":35,"bg":"hospital_day","cast":["chengye"],"steps":[{"t":"cast","list":["chengye"],"focus":"chengye"},{"t":"n","text":"他是自己去的医院。你到的时候，他已经在走廊的塑料椅上坐了四十分钟。"},{"t":"n","text":"诊室的门开着一条缝，里面有人在说话。"},{"t":"n","text":"他手里捏着一张挂号单，边角被捏得起了毛。"},{"t":"n","text":"叫号机响了一声。他站起来，走了两步，回头看你。"},{"t":"c","id":"chengye","text":"你在外面等。"},{"t":"n","text":"你说你进去。"},{"t":"n","text":"他犹豫了一下，把门推开了。"},{"t":"n","text":"医生让他躺到床上，把裤腿卷上去。"},{"t":"n","text":"膝盖比上次肿。脚踝也是。医生按了几个地方，问他疼不疼。他每次都说「还行」。"},{"t":"n","text":"医生说，要抽一下。"},{"t":"n","text":"针管拿出来的时候，他转过头，看着墙上的那张人体骨骼图。"},{"t":"n","text":"他没有说话。他的手放在身体两侧，攥着床单。"},{"t":"n","text":"抽完，医生把针管丢进托盘，说了几句，语速很快。"},{"t":"n","text":"「软骨磨损。」「不能再这么练。」「再打两年，这条腿就得换个零件。」"},{"t":"n","text":"程野从床上坐起来，把裤腿放下来。"},{"t":"c","id":"chengye","text":"换就换呗。"},{"t":"n","text":"医生抬头看了他一眼，没接话。"},{"t":"n","text":"医生在处方单背面画了三个动作：一个抬腿，一个靠墙蹲，一个踮脚。"},{"t":"n","text":"「每天做。做三个月。」"},{"t":"n","text":"程野把单子折好，放进口袋。"},{"t":"n","text":"走到走廊，他忽然停下，扶着墙，把那条腿慢慢抬起来，抬到一半放下。"},{"t":"c","id":"chengye","text":"这个。我在宿舍练。"},{"t":"n","text":"走廊里有人推着车过去，轮子在地砖上响。"},{"t":"n","text":"他又抬了一次。这次抬得高一点，停了三秒。"},{"t":"n","text":"出了诊室，他把外套穿上，用袖子把手心的印子挡住。"},{"t":"n","text":"走廊尽头的窗户开着，风把窗帘吹起来。"},{"t":"c","id":"chengye","text":"不疼。"},{"t":"n","text":"他说。"},{"t":"n","text":"走出医院大门，他在台阶上坐下来。"},{"t":"n","text":"大门旁边有个便利店。你进去买了两瓶水，出来的时候，他把片子又拿出来看了一遍。"},{"t":"n","text":"「这块黑的，」他说，「就是磨掉的地方。」"},{"t":"n","text":"你说你看不懂。"},{"t":"c","id":"chengye","text":"我也看不懂。医生说的时候，我就一直点头。"},{"t":"n","text":"太阳很大，晒得台阶发烫。"},{"t":"c","id":"chengye","text":"这事别跟我妈说。"},{"t":"n","text":"你说，那你自己呢。"},{"t":"n","text":"他从兜里摸出那张片子，对着太阳看。黑白的，看不懂。"},{"t":"c","id":"chengye","text":"我要是不能跑了，我还能干嘛。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"陪他坐在台阶上，坐很久","hint":"不说话 · 坐着就行","eff":{"aff":6.0,"stress":-2.0,"happy":2.0},"reply":[{"t":"n","text":"你们坐了很久。门口的人来来去去，有一辆救护车开走，没有拉响警报。"},{"t":"n","text":"他的影子从脚边慢慢挪到台阶下面。"},{"t":"n","text":"他忽然把片子折起来，塞进口袋。"},{"t":"c","id":"chengye","text":"走。我饿了。"},{"t":"n","text":"他站起来，拍了拍裤子。"},{"t":"c","id":"chengye","text":"你请。"}]},{"label":"B","text":"说「那你就别跑了，现在」","hint":"把最狠的话说在前面","eff":{"aff":2.0,"eq":2.0,"stress":-3.0},"reply":[{"t":"n","text":"他笑了一下，笑得没什么力气。"},{"t":"n","text":"他把片子举起来，对着太阳。"},{"t":"c","id":"chengye","text":"再一年。"},{"t":"n","text":"他说。"},{"t":"c","id":"chengye","text":"拿到一级运动员证，我就能当教练。教练不用跑。"},{"t":"n","text":"他把片子收起来，折成很小一块。"},{"t":"c","id":"chengye","text":"我算过。一年。一年之后我就不跑了。"}]},{"label":"C","text":"说「这事得让你妈知道」","hint":"有些事不该瞒","eff":{"aff":3.0,"eq":3.0,"stress":2.0},"reply":[{"t":"n","text":"他低着头，很久没说话。"},{"t":"n","text":"台阶上有一片落叶，他用鞋尖蹭了两下。"},{"t":"c","id":"chengye","text":"等这赛季完。"},{"t":"n","text":"你说，你要是拖到她从别人嘴里知道。"},{"t":"n","text":"他把手撑在台阶上。"},{"t":"c","id":"chengye","text":"我知道。"},{"t":"n","text":"他抬起头，眼睛有点红，但没有哭。"},{"t":"c","id":"chengye","text":"我就是不知道怎么跟她说。她一个人把我拉扯大，我到现在，还是让她操心。"}]}]},{"t":"n","text":"回去的公交车上，他把头靠在车窗上睡着了。"},{"t":"n","text":"窗外的路灯一盏一盏过去，照一下，暗一下。"},{"t":"n","text":"你看见他球鞋的鞋带松了，掉在过道上。"},{"t":"n","text":"你弯腰，把它系上。"},{"t":"n","text":"他醒了。"},{"t":"c","id":"chengye","text":"到哪了。"},{"t":"n","text":"你说，快了。"},{"t":"n","text":"他坐直了，揉了揉脸，忽然说："},{"t":"c","id":"chengye","text":"我做梦了。梦见我在跑，但是跑不动，腿跟灌了铅一样。"},{"t":"n","text":"他看着窗外。"},{"t":"c","id":"chengye","text":"旁边的人都过去了。我一个人在那儿跑。"},{"t":"n","text":"车到站了。他站起来，把包背上。"},{"t":"c","id":"chengye","text":"不过没事。做梦嘛。"}],"id":"chengye_13"},{"no":14,"title":"毕业前的球场","week":39,"bg":"court_day","cast":["chengye"],"steps":[{"t":"cast","list":["chengye"],"focus":"chengye"},{"t":"n","text":"六月的球场是空的。放暑假了，篮架下面长了几根草。"},{"t":"n","text":"边上那盏灯亮着，飞虫在灯罩里撞。"},{"t":"n","text":"他刚跑完。球衣湿了一半，贴在背上。他仰着头喝水，喉结一下一下地动。"},{"t":"n","text":"看见你，他把水瓶放下，冲你招手。"},{"t":"c","id":"chengye","text":"站那干嘛，进来啊。"},{"t":"n","text":"他把脚边的球踢过来。"},{"t":"n","text":"你没接住。球从手边滚过去，滚到场边，撞在铁栏杆上，弹回来一点。"},{"t":"n","text":"他笑了，走过来捡。"},{"t":"n","text":"走到一半，他慢下来。左脚落地的时候，有一点不自然，像在避开某个角度。"},{"t":"n","text":"他把球捡起来，抱在手里，走到你面前。"},{"t":"n","text":"你问他：「脚怎么了。」"},{"t":"n","text":"他把球往地上一按，接住。"},{"t":"c","id":"chengye","text":"没事。"},{"t":"n","text":"他顿了一下。"},{"t":"c","id":"chengye","text":"医生说，再打两年，可能就得换了。"},{"t":"n","text":"他说得很轻松，像在说别人的事。"},{"t":"n","text":"他把球扔给你。你这次接住了。"},{"t":"n","text":"球面上有一道用记号笔写的字，已经磨得快看不见了：「7」。"},{"t":"c","id":"chengye","text":"南方有个俱乐部，给我发了合同。两年。"},{"t":"n","text":"他从裤兜里掏出一张折了四折的纸，展开给你看。纸上有俱乐部的抬头，有他的名字，有薪水的数字。"},{"t":"n","text":"薪水比他现在多三倍。"},{"t":"c","id":"chengye","text":"我妈让我回去。"},{"t":"n","text":"他把纸折回去，折得很整齐。"},{"t":"c","id":"chengye","text":"她说，店盘出去了，人也该回来了。"},{"t":"n","text":"他抬头看了看那个篮筐。"},{"t":"c","id":"chengye","text":"她没说让我别去。她就说，你自己看着办。"},{"t":"n","text":"球场边上有一排看台，三级台阶，水泥的。"},{"t":"n","text":"他在最下面那一级坐下，把球夹在两腿之间。"},{"t":"n","text":"你在他旁边坐下。灯在头顶，两个人的影子叠在一起。"},{"t":"n","text":"他忽然安静了。不是平时那种笑完的停顿，是真的安静。"},{"t":"n","text":"安静了很久。"},{"t":"c","id":"chengye","text":"我下个月走。"},{"t":"n","text":"他说。"},{"t":"c","id":"chengye","text":"走之前，我想跟你说个事。"},{"t":"n","text":"他看着地面，用鞋尖碾一颗小石子。"},{"t":"c","id":"chengye","text":"想了挺久了。从你第一次来球场那次开始想。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"把话说出口","hint":"说出口 · 这段关系会变","eff":{"aff":8.0,"happy":6.0,"stress":-4.0,"flag2":true,"lover":true},"reply":[{"t":"n","text":"你说完了。"},{"t":"n","text":"他没有立刻回答。他把手里的球转了一下，又转回去。"},{"t":"n","text":"然后他笑起来，露出那颗小虎牙。"},{"t":"c","id":"chengye","text":"你早说啊。"},{"t":"n","text":"他伸手揉了一下你的头，力气有点大，把你的头发弄乱了。"},{"t":"n","text":"你看他，他移开视线，耳朵红了。"},{"t":"c","id":"chengye","text":"我一直以为是我一个人在这儿想。"},{"t":"n","text":"他把球放到一边，两只手撑在台阶上。"},{"t":"c","id":"chengye","text":"那以后，我跑快一点，早点回来。"},{"t":"n","text":"你说，你跑慢一点也行。"},{"t":"n","text":"他想了想。"},{"t":"c","id":"chengye","text":"那不行。习惯了。"},{"t":"n","text":"他从包里翻出一样东西，塞给你。"},{"t":"n","text":"是一张票。南方俱乐部的第一场主场比赛，观众席，一区一排。"},{"t":"c","id":"chengye","text":"这次是真的第一排。我买了。"},{"t":"n","text":"他说。"},{"t":"c","id":"chengye","text":"你能来吗。"},{"t":"n","text":"你说能。"},{"t":"n","text":"他低下头，笑了一声，肩膀塌下去一点，像是把什么放下了。"}]},{"label":"B","text":"说「那你以后怎么办」","hint":"先问以后 · 现实一点","eff":{"aff":3.0,"happy":-2.0,"stress":2.0},"reply":[{"t":"n","text":"他低头看了看自己的脚。"},{"t":"c","id":"chengye","text":"不知道。"},{"t":"n","text":"他把球放在膝盖上。"},{"t":"c","id":"chengye","text":"当教练？开饭馆？"},{"t":"n","text":"他笑了一下，有点勉强。"},{"t":"c","id":"chengye","text":"反正总得有个去处。"},{"t":"n","text":"你说，你打球的时候，眼睛很亮。"},{"t":"n","text":"他抬起头看你。"},{"t":"n","text":"过了一会儿，他说：「那要是不打了呢。」"},{"t":"n","text":"你没有接话。"},{"t":"n","text":"那天晚上，你们在球场边坐到很晚。灯关了一半，剩下那盏一闪一闪。"}]},{"label":"C","text":"用玩笑带过","hint":"把话咽回去 · 气氛还在","eff":{"aff":-3.0,"eq":2.0,"happy":-3.0},"reply":[{"t":"n","text":"你说：「那你以后可以来给我当司机。」"},{"t":"n","text":"他愣了一秒，然后哈哈大笑。笑声在空球场上撞了一下，散开。"},{"t":"c","id":"chengye","text":"行啊。包吃包住。"},{"t":"n","text":"你说，还包五险一金。"},{"t":"c","id":"chengye","text":"那我干。"},{"t":"n","text":"他笑得眼睛弯起来，笑完，把球捡起来。"},{"t":"c","id":"chengye","text":"再来一局？"},{"t":"n","text":"你说来。"},{"t":"n","text":"他投了一个，没进。你投了一个，也没进。"},{"t":"n","text":"球滚到一边，谁也没有去捡。"}]}]},{"t":"n","text":"走出校门的时候，门卫室的大爷在听收音机，声音很小。"},{"t":"n","text":"程野回头看了一眼球场。灯还亮着。"},{"t":"c","id":"chengye","text":"这个场子，我从初中打到现在。"},{"t":"n","text":"他把包换到另一边肩上。"},{"t":"c","id":"chengye","text":"草都长出来了。"},{"t":"block","when":"low","steps":[{"t":"n","text":"他在最下面那一级坐下，把球夹在两腿之间。"},{"t":"n","text":"他张了张嘴，又合上。"},{"t":"n","text":"「算了。」他说。"},{"t":"n","text":"你问算什么。"},{"t":"n","text":"他摇摇头，把球往地上一按。"},{"t":"c","id":"chengye","text":"没什么。等我回来再说。"},{"t":"n","text":"你在球场边站到天黑。他投完最后一个球，走过来，把球夹在胳膊底下。"},{"t":"c","id":"chengye","text":"走吧，请你喝汽水。"},{"t":"n","text":"你们走到小卖部，发现已经关门了。卷帘门拉下来，上面贴着一张纸：「暑假暂停营业」。"},{"t":"n","text":"他挠了挠头。"},{"t":"c","id":"chengye","text":"那下次。"},{"t":"n","text":"你说好。"},{"t":"n","text":"他把球放到包里，拉链拉到一半，停住了。"},{"t":"c","id":"chengye","text":"我刚才想说的事。"},{"t":"n","text":"他抬起头。"},{"t":"c","id":"chengye","text":"算了。等我从南方回来。两年。"},{"t":"n","text":"他拉上拉链。"},{"t":"c","id":"chengye","text":"两年之后，我还站在这儿。"}]}],"id":"chengye_14"},{"no":15,"title":"站台","week":41,"bg":"station_dusk","cast":["chengye"],"steps":[{"t":"cast","list":["chengye"],"focus":"chengye"},{"t":"n","text":"站台上的风比外面大。广播一遍一遍念着车次，念到一半被人声盖过去。"},{"t":"n","text":"他背着一个很大的双肩包，包带勒在肩上，把球衣的肩线压出两道印。"},{"t":"n","text":"包的侧兜里塞着一个玻璃瓶，用毛巾裹着，毛巾的角露在外面。"},{"t":"n","text":"你问那是什么。"},{"t":"c","id":"chengye","text":"辣酱。我妈做的。她说南方吃不惯，让我带着。"},{"t":"n","text":"他把包放上行李架，动作很熟，一只手托底，一只手扶边。放好以后还拍了拍。"},{"t":"n","text":"他站在车门边，没有上去。"},{"t":"c","id":"chengye","text":"合同签了两年。"},{"t":"n","text":"他说。"},{"t":"c","id":"chengye","text":"两年以后，我二十五。"},{"t":"n","text":"他算了算，又补了一句。"},{"t":"c","id":"chengye","text":"二十五，还能跑。"},{"t":"n","text":"火车站的电子屏在头顶滚，红色的字一串一串过去。"},{"t":"n","text":"他从包里掏出一张纸，展开。是他宿舍墙上那张训练计划表，被撕下来了，边缘毛着。"},{"t":"n","text":"表格背面是空白的。他把纸翻过来给你看。"},{"t":"c","id":"chengye","text":"你帮我拿着。"},{"t":"n","text":"你说这算什么。"},{"t":"c","id":"chengye","text":"算个凭据。"},{"t":"n","text":"他把纸塞到你手里。"},{"t":"c","id":"chengye","text":"两年以后，我来拿回去。"},{"t":"n","text":"广播开始念这趟车。他往车门那边看了一眼，又转回来。"},{"t":"c","id":"chengye","text":"到了给你发消息。"},{"t":"n","text":"你说好。"},{"t":"c","id":"chengye","text":"你别老熬夜。"},{"t":"n","text":"你说你也是。"},{"t":"n","text":"你问，你妈没来送？"},{"t":"n","text":"他把包带往肩上提了提。"},{"t":"c","id":"chengye","text":"没让她来。她一来就哭。"},{"t":"n","text":"他顿了一下。"},{"t":"c","id":"chengye","text":"她一哭，我就走不了了。"},{"t":"n","text":"他笑了一下。"},{"t":"c","id":"chengye","text":"我作息比你好。我六点就起。"},{"t":"n","text":"他忽然想起什么，弯腰从包里掏出一个塑料袋，里面两个面包。"},{"t":"c","id":"chengye","text":"给你买的。车上吃。"},{"t":"n","text":"你说你是来送他的，怎么成了他给你买。"},{"t":"n","text":"他把袋子塞进你手里。"},{"t":"c","id":"chengye","text":"我坐车不爱吃东西。晃。"},{"t":"n","text":"面包是奶油的，被压扁了一点。他看了看，说：「压了。」"},{"t":"n","text":"然后他又说：「压了也能吃。」"},{"t":"n","text":"广播又念了一遍车次。他把包往上提了提，侧兜里那个玻璃瓶磕在行李架上，响了一声。他伸手扶住，扶稳了才松开。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"说「两年后我去接你」","hint":"把约定说死","eff":{"aff":5.0,"happy":4.0,"stress":-1.0},"reply":[{"t":"n","text":"他点头，点得很用力。"},{"t":"c","id":"chengye","text":"那你可得记着。我记性好。"},{"t":"n","text":"他说完自己先笑了。"},{"t":"c","id":"chengye","text":"骗你的。我记性不好。所以你记着。"}]},{"label":"B","text":"说「你别回来了，在那边好好打」","hint":"把他往外推一把","eff":{"aff":2.0,"happy":-1.0,"stress":2.0},"reply":[{"t":"n","text":"他没有马上回答。他看着站台尽头，那边有一段铁轨并到一起。"},{"t":"c","id":"chengye","text":"我妈在这儿。"},{"t":"n","text":"他说。"},{"t":"c","id":"chengye","text":"我得回来。"},{"t":"n","text":"他把手插进兜里。"},{"t":"c","id":"chengye","text":"我知道你是好意。"}]},{"label":"C","text":"什么都不说，抱他一下","hint":"不用说的 · 就不说","eff":{"aff":6.0,"happy":3.0,"stress":-2.0},"reply":[{"t":"n","text":"你上前一步。"},{"t":"n","text":"他愣了一下，手停在半空，然后落下来，拍了拍你的背。"},{"t":"n","text":"他身上的味道是洗衣粉和汗。"},{"t":"n","text":"他拍得很轻，拍了两下，手停在那儿。"},{"t":"n","text":"他声音有点闷。"},{"t":"c","id":"chengye","text":"哎，松了。要开了。"},{"t":"n","text":"你没松。他也没动。"}]}]},{"t":"n","text":"他上了车，站在车门边。"},{"t":"n","text":"车要开的时候，他把车窗推上去，探出半个身子。"},{"t":"c","id":"chengye","text":"记着啊！第一排！"},{"t":"n","text":"车窗是自动回弹的，卡在中间。他用手按住，一直按到车开动。"},{"t":"n","text":"玻璃上有一层灰。你伸手擦了一下。"},{"t":"n","text":"车已经动了。他在玻璃那边，抬手拍了拍。"},{"t":"n","text":"你跟着走了几步，被站台上的工作人员拦了一下。"},{"t":"n","text":"车开出去，越来越快，尾灯在铁轨尽头拐了个弯。"},{"t":"n","text":"你的手机响了。"},{"t":"n","text":"他发来一条："},{"t":"n","text":"「刚才你擦玻璃的样子，好傻。」"},{"t":"n","text":"过了一会儿，又发来一条。"},{"t":"n","text":"「我到了跟你说。你回去路上小心。」"},{"t":"n","text":"再没有别的了。"},{"t":"n","text":"你把那张训练计划表折好，放进口袋里。纸上还留着他宿舍墙上的胶带印。"}],"id":"chengye_15"}]},{"id":"ch3","title":"第三章 · 职场","scenes":[{"no":16,"title":"客场","week":45,"bg":"gym_day","cast":["chengye"],"steps":[{"t":"cast","list":["chengye"],"focus":"chengye"},{"t":"n","text":"你下班的时间是六点，实际走出写字楼是七点四十。"},{"t":"n","text":"体育馆在城南，要换两趟地铁。你到的时候，比赛已经打到第三节。"},{"t":"n","text":"看台只坐了一半人。你找了个靠后的位置，看见他在替补席上。"},{"t":"n","text":"他穿着那件 7 号，坐得很直，两条腿伸在前面，手肘撑在膝盖上。"},{"t":"n","text":"场上跑的是几个年轻队员。有一个特别快，每次接球都要冲一下。"},{"t":"n","text":"教练喊暂停的时候，程野站起来，给下场的队员递水，拍了一下对方的背。"},{"t":"n","text":"整场，他没有被换上去。"},{"t":"n","text":"比赛结束，主队赢了。观众往外走，你逆着人流往后门去。"},{"t":"n","text":"后门是一条小巷，路灯坏了两个，只剩一个亮着。"},{"t":"n","text":"他坐在台阶上，手里两瓶汽水，一瓶已经不冰了。"},{"t":"n","text":"看见你，他站起来，汽水在手里晃了一下。"},{"t":"c","id":"chengye","text":"你还真来了。"},{"t":"n","text":"他瘦了。肩膀还是宽，但脸小了一圈，颧骨有点突。"},{"t":"n","text":"他把那瓶冰的递给你。"},{"t":"c","id":"chengye","text":"今天没上。"},{"t":"n","text":"他说得很自然，像在说天气。"},{"t":"c","id":"chengye","text":"教练说要练新人。"},{"t":"n","text":"他拧开自己那瓶，喝了一口，皱了皱眉。"},{"t":"c","id":"chengye","text":"热的。"},{"t":"n","text":"两个人坐在台阶上。巷子外面是主路，车灯一晃一晃地照进来。"},{"t":"n","text":"他脚上那双鞋是旧的，鞋头开了一点胶，用胶水粘过，粘痕发白。"},{"t":"n","text":"「新鞋在包里。」他说，「比赛才穿。平时舍不得。」"},{"t":"n","text":"他把球衣的下摆从裤腰里拽出来，上面全是汗，贴在身上不舒服。"},{"t":"n","text":"过了一会儿，他说："},{"t":"c","id":"chengye","text":"我们队里有个小孩，十九岁。"},{"t":"n","text":"他把汽水瓶放在脚边。"},{"t":"c","id":"chengye","text":"跑一分五十一。"},{"t":"n","text":"他说这个数字的时候，语气很平，但停了一下才继续。"},{"t":"c","id":"chengye","text":"我最好成绩一分五十三。"},{"t":"n","text":"他把手在裤子上擦了一下。"},{"t":"n","text":"他从兜里摸出手机，翻了两下，递过来。"},{"t":"n","text":"是一段视频。训练馆里，一群孩子在跑折返。镜头晃得厉害，是他自己举着手机拍的。"},{"t":"n","text":"视频最后，一个小孩跑过来，冲着镜头喊：「程教练你别拍了！」"},{"t":"n","text":"他把手机收回去。"},{"t":"c","id":"chengye","text":"跑得乱七八糟。"},{"t":"n","text":"他嘴上这么说，嘴角是翘着的。"},{"t":"c","id":"chengye","text":"十九岁的时候，我也以为自己能一直快下去。"},{"t":"n","text":"他抬头看着巷子尽头那盏路灯。"},{"t":"c","id":"chengye","text":"我以前觉得我能跑到二十六。"},{"t":"n","text":"他顿了很久。"},{"t":"c","id":"chengye","text":"现在我觉得，我可能跑不到二十五。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"说「你才二十三，还有三年」","hint":"把数字摆出来","eff":{"aff":4.0,"happy":2.0,"stress":-2.0},"reply":[{"t":"n","text":"他抬起头看你。"},{"t":"c","id":"chengye","text":"三年。"},{"t":"n","text":"他重复了一遍，像在算。"},{"t":"c","id":"chengye","text":"三年，一千多天。一天练两次。"},{"t":"n","text":"他笑了一下，笑得有点狠。"},{"t":"c","id":"chengye","text":"行。那就练。"}]},{"label":"B","text":"说「不上场也挺好，至少不伤」","hint":"从身体说起","eff":{"aff":2.0,"eq":2.0,"stress":1.0},"reply":[{"t":"n","text":"他没有说话。"},{"t":"n","text":"他低头看自己的脚，看了很久。"},{"t":"c","id":"chengye","text":"你也这么说。"},{"t":"n","text":"他抬起头。"},{"t":"c","id":"chengye","text":"上个月我妈也这么说。她说，不打就不打了，回来。"},{"t":"n","text":"他把汽水瓶转了一圈。"},{"t":"c","id":"chengye","text":"可我要是不打了，我拿什么回去。"}]},{"label":"C","text":"什么都不说，陪他走回酒店","hint":"路不长 · 走着就行","eff":{"aff":6.0,"stress":-2.0,"happy":2.0},"reply":[{"t":"n","text":"酒店离体育馆两站路。他把包背在肩上，走得很慢。"},{"t":"n","text":"路过一家便利店，他停下来，进去买了一包话梅，出来递给你。"},{"t":"c","id":"chengye","text":"这个。以前我妈给我买。"},{"t":"n","text":"他拆开自己那一颗，含在嘴里，说话有点含糊。"},{"t":"c","id":"chengye","text":"含着这个跑，嘴里不干。"},{"t":"n","text":"走到酒店门口，他站住了。"},{"t":"c","id":"chengye","text":"明天我们一早就走。"}]}]},{"t":"n","text":"酒店的大堂很亮，前台的服务员在打哈欠。"},{"t":"n","text":"他把包换了个肩。"},{"t":"c","id":"chengye","text":"你明天上班吧。"},{"t":"n","text":"你说嗯。"},{"t":"c","id":"chengye","text":"那我不送你了。"},{"t":"n","text":"你说好。你走了几步。"},{"t":"n","text":"他在后面喊："},{"t":"c","id":"chengye","text":"哎。"},{"t":"n","text":"你回头。他站在酒店门口那一片光里，手插在兜里。"},{"t":"c","id":"chengye","text":"没事。就想喊一声。"},{"t":"n","text":"他抬了抬下巴，笑了一下。"}],"id":"chengye_16"},{"no":17,"title":"卷帘门","week":47,"bg":"izakaya_night","cast":["chengye"],"steps":[{"t":"cast","list":["chengye"],"focus":"chengye"},{"t":"n","text":"你请了一天假，坐最早的一班车回去。"},{"t":"n","text":"巷口的卷帘门拉下来一半。门口的塑料凳叠在一起，用绳子捆着。"},{"t":"n","text":"招牌还挂着。「程家小馆」四个字，第二个字的漆掉得更多了。"},{"t":"n","text":"店里在收拾东西。桌子还在，椅子搬到墙边，冰柜的门开着，里面空了。"},{"t":"n","text":"程野在后厨。他穿着围裙，袖子卷起来，正在刷一个很大的汤锅。"},{"t":"n","text":"水开得很大。他刷得很用力，泡沫溅到胳膊上。"},{"t":"n","text":"你站在门口喊了一声。他没有回头。"},{"t":"c","id":"chengye","text":"水声大，我听不见你说话。"},{"t":"n","text":"你走过去，把他手边的水龙头关小了。"},{"t":"n","text":"他这才转过头。"},{"t":"n","text":"他的眼睛是红的。脸上有水，分不清是溅的还是别的。"},{"t":"c","id":"chengye","text":"辣椒。"},{"t":"n","text":"他说，抬手指了指灶台上那盆辣椒油。"},{"t":"c","id":"chengye","text":"呛的。"},{"t":"n","text":"前厅传来他妈妈的声音：「小野，王叔来了。」"},{"t":"n","text":"他擦了擦手，把围裙解下来。"},{"t":"n","text":"王叔在门口站着，手里一个信封，鼓鼓的。"},{"t":"n","text":"「听说你们要关门。」他说，「欠的账，今天都清了。」"},{"t":"n","text":"他把信封放在桌上。"},{"t":"n","text":"程野打开看，数了一下，比赊账本上的多。"},{"t":"c","id":"chengye","text":"王叔，多了。"},{"t":"n","text":"「不多。」王叔说，「你家那几年，我吃了多少碗面，我记着。」"},{"t":"n","text":"他妈妈从后面出来，两只手在围裙上擦。"},{"t":"n","text":"「不用不用。」她说，「真的不用。」"},{"t":"n","text":"王叔把信封往桌上一按，转身走了。"},{"t":"n","text":"走到门口，他回头说了一句："},{"t":"n","text":"「以后要是再开，记得叫我。」"},{"t":"n","text":"王叔走了以后，他妈妈把那个信封拿起来，捏在手里，没有打开。"},{"t":"n","text":"她在桌边坐下，把信封放在腿上，一只手压着。"},{"t":"n","text":"「手术费八万。」她说，声音很轻，「不做了。做完了也干不了活了。」"},{"t":"n","text":"程野正在收桌子。他停下来，把手里的碗放下。"},{"t":"c","id":"chengye","text":"做。"},{"t":"n","text":"他只说了一个字。"},{"t":"n","text":"他妈妈抬起头看他。"},{"t":"c","id":"chengye","text":"钱我有。你别管。"},{"t":"n","text":"他说完，转身进了后厨。水声又响起来。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"帮他把碗洗完","hint":"手上做点事","eff":{"aff":5.0,"happy":2.0,"familyRel":2.0},"reply":[{"t":"n","text":"水是热的。碗很油，洗洁精打了两遍才起泡。"},{"t":"n","text":"他站在旁边擦。两个人一人洗，一人擦，不说话。"},{"t":"n","text":"洗到最后一个，是一个有豁口的小碗。"},{"t":"n","text":"他接过去，没有放到柜子里，而是用毛巾擦干，放进了自己的包。"},{"t":"c","id":"chengye","text":"这个是我的。从小用。"}]},{"label":"B","text":"说「你退了，然后呢」","hint":"问到实处","eff":{"aff":2.0,"eq":2.0,"stress":2.0},"reply":[{"t":"n","text":"他把抹布挂在水龙头上。"},{"t":"c","id":"chengye","text":"当教练。"},{"t":"n","text":"他从包里翻出一个红色的本子，塑料封皮，递给你。"},{"t":"n","text":"是一级运动员证。照片是他十八岁那年拍的，头发短得能看见头皮。"},{"t":"c","id":"chengye","text":"去年考的。考了两次。"},{"t":"n","text":"他把证收回去。"},{"t":"c","id":"chengye","text":"体校那边，教练岗有空缺。我打过电话了。"},{"t":"n","text":"你说，你早就想好了。"},{"t":"c","id":"chengye","text":"嗯。想了两年。"}]},{"label":"C","text":"去前厅陪他妈妈说话","hint":"先陪长辈","eff":{"aff":4.0,"familyRel":3.0,"happy":2.0},"reply":[{"t":"n","text":"他妈妈在擦收银台。台面已经擦得很干净了，她还在擦。"},{"t":"n","text":"你搬了张凳子坐在旁边。"},{"t":"n","text":"她说了很多：这条巷子哪年修的，哪家孩子考上了大学，哪年冬天雪大，把雨棚压塌了。"},{"t":"n","text":"说到最后，她说："},{"t":"n","text":"「他小时候，就坐这个台子底下写作业。桌子小，字写得丑。」"},{"t":"n","text":"她笑了一下。"},{"t":"n","text":"「现在要关了。我这心里，空。」"}]}]},{"t":"n","text":"九点，东西收得差不多了。"},{"t":"n","text":"他妈妈把门口那块招牌摘下来，靠在墙边。"},{"t":"n","text":"木头的，很沉。她一个人抬不动，程野过去接了。"},{"t":"c","id":"chengye","text":"妈，这个我带走。"},{"t":"n","text":"「带走干嘛。」她说，「又不值钱。」"},{"t":"n","text":"他把招牌靠在自己腿上，用手抹了一下上面的灰。"},{"t":"c","id":"chengye","text":"值钱。"},{"t":"n","text":"他妈妈看了他一眼，没有再说什么。"},{"t":"n","text":"她把一串钥匙放在桌上。"},{"t":"n","text":"「房东说明天来收。」她说，「你们年轻人，别在这儿耗着了。都回去吧。」"},{"t":"n","text":"程野把钥匙拿起来，握在手里，握了一会儿。"}],"id":"chengye_17"},{"no":18,"title":"替补席","week":49,"bg":"gym_day","cast":["chengye"],"steps":[{"t":"cast","list":["chengye"],"focus":"chengye"},{"t":"n","text":"这场是主场，票卖得不错。看台上有人举牌子，写着那个十九岁小孩的名字。"},{"t":"n","text":"程野坐在替补席最边上。整场四十分钟，他没有被叫到。"},{"t":"n","text":"他把毛巾搭在膝盖上，一直没有动。"},{"t":"n","text":"暂停的时候他站起来，把水递过去。有人下场，他拍一下对方的背。"},{"t":"n","text":"比赛结束，主队赢了十二分。全场鼓掌。"},{"t":"n","text":"他没有跟队里一起回更衣室。他在通道口站着，等教练。"},{"t":"n","text":"教练出来，两个人说了大概五分钟。你隔着一段距离，看见他一直在点头。"},{"t":"n","text":"教练拍了拍他的肩，走了。"},{"t":"n","text":"他转过身，看见你，脸上还有笑。"},{"t":"c","id":"chengye","text":"走，吃饭。"},{"t":"n","text":"你说你请。"},{"t":"c","id":"chengye","text":"行。"},{"t":"n","text":"饭馆在体育馆后面，一家烧烤摊。他点了很多东西，最后没吃完。"},{"t":"n","text":"他吃了几串就不动了，坐在那儿，把竹签一根一根摆整齐。"},{"t":"n","text":"老板端着一盘烤好的东西过来，多放了两串。"},{"t":"n","text":"「程教练。」老板说，「我儿子在你那儿练。」"},{"t":"n","text":"程野抬起头，笑了一下。"},{"t":"c","id":"chengye","text":"哪个？"},{"t":"n","text":"「瘦的那个。跑不快。」"},{"t":"n","text":"程野想了想。"},{"t":"c","id":"chengye","text":"跑不快不要紧。他传球好。"},{"t":"n","text":"老板愣了一下，笑得眼睛都没了，又回炉上拿了两串过来。"},{"t":"n","text":"程野把多的那两串推到一边。"},{"t":"c","id":"chengye","text":"吃不完。打包。"},{"t":"n","text":"忽然，他说："},{"t":"c","id":"chengye","text":"我今天坐在那儿，看那个小孩跑。"},{"t":"n","text":"他把最后一根竹签摆好。"},{"t":"c","id":"chengye","text":"我想，我十九岁的时候，也是那样。"},{"t":"n","text":"他抬起头。"},{"t":"c","id":"chengye","text":"我除了跑，什么都不会。这句话我说了十年。"},{"t":"n","text":"他停住。"},{"t":"c","id":"chengye","text":"今天我发现，我说错了。"},{"t":"n","text":"他把手在桌上摊开。"},{"t":"c","id":"chengye","text":"我还会看。"},{"t":"n","text":"他说。"},{"t":"c","id":"chengye","text":"谁该在什么时候加速，谁的后半程不行，谁跑到第三个弯道会往外飘——我一看就知道。"},{"t":"n","text":"他指了指自己的眼睛。"},{"t":"c","id":"chengye","text":"教练说，让我下赛季带青年组。"},{"t":"n","text":"他说这句话的时候，手在桌上按了一下。"},{"t":"c","id":"chengye","text":"他说，你这双眼睛，比你的腿值钱。"},{"t":"n","text":"他忽然来了精神，把手里的签子往桌上一放。"},{"t":"c","id":"chengye","text":"就那个十九岁的，他第三个弯道一定往外飘。他自己不知道。我跟他说了三次。"},{"t":"n","text":"他用手指在桌上画了一条弧线，画完又把那条线擦掉。"},{"t":"c","id":"chengye","text":"他前半程太快。前面冲得凶，后面就没劲。我让他把第一个两百压住。"},{"t":"n","text":"他抬起头。"},{"t":"c","id":"chengye","text":"他上周跑了一分四十九。"},{"t":"n","text":"他说这个数字的时候，眼睛是亮的，像在说自己的成绩。"},{"t":"n","text":"说完他自己也发现了，愣了一下，然后挠了挠头。"},{"t":"c","id":"chengye","text":"你看我。说别人的成绩，比说自己还高兴。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"说「那你带啊」","hint":"顺着他 · 往下推","eff":{"aff":5.0,"happy":3.0,"stress":-2.0},"reply":[{"t":"n","text":"他点头。"},{"t":"c","id":"chengye","text":"带。"},{"t":"n","text":"他拿起一串没吃完的，咬了一口，嚼得很用力。"},{"t":"c","id":"chengye","text":"一群十三四岁的，正是最难带的时候。"},{"t":"n","text":"他嘴上这么说，眼睛是亮的。"}]},{"label":"B","text":"问他「你想带吗」","hint":"不替他决定","eff":{"aff":6.0,"eq":2.0,"happy":2.0},"reply":[{"t":"n","text":"他愣住了。"},{"t":"n","text":"好像这十年，没有人问过他「你想不想」。"},{"t":"n","text":"他想了很久，久到烧烤摊的老板过来收了一次盘子。"},{"t":"c","id":"chengye","text":"想。"},{"t":"n","text":"他说完，自己也有点意外。"},{"t":"c","id":"chengye","text":"我以为我会说不想。"},{"t":"n","text":"他笑了一下。"},{"t":"c","id":"chengye","text":"结果我说想。"}]},{"label":"C","text":"说「那你以后是不是就不跑了」","hint":"问一句 · 会疼","eff":{"aff":3.0,"happy":-1.0,"stress":1.0},"reply":[{"t":"n","text":"他没有马上回答。"},{"t":"n","text":"他把手里的杯子转了半圈。"},{"t":"c","id":"chengye","text":"跑。"},{"t":"n","text":"他说。"},{"t":"c","id":"chengye","text":"跑到跑不动为止。"},{"t":"n","text":"他抬起头。"},{"t":"c","id":"chengye","text":"但不是为了名单了。"}]}]},{"t":"n","text":"吃完饭，他送你到地铁口。"},{"t":"n","text":"路上他一直没说话，走到地铁口才开口。"},{"t":"c","id":"chengye","text":"我下个月退役赛。老馆。"},{"t":"n","text":"他说得很随便，像在说明天吃什么。"},{"t":"n","text":"然后他补了一句："},{"t":"c","id":"chengye","text":"你来吗。"},{"t":"n","text":"不是问句的语气。是问句。"}],"id":"chengye_18"},{"no":19,"title":"退役赛","week":51,"bg":"gym_day","cast":["chengye"],"steps":[{"t":"cast","list":["chengye"],"focus":"chengye"},{"t":"n","text":"南方的合同到期，他没有续。"},{"t":"n","text":"回来那天，他去队里交了球衣，把柜子清空，只带回一双鞋和一个哨子。"},{"t":"n","text":"体校老馆在城北，外墙是红砖的，墙皮掉了一块，露出里面的水泥。"},{"t":"n","text":"门口挂着一条横幅，红底白字：「程野退役表演赛」。字是手写的，最后一个「赛」字有点挤。"},{"t":"n","text":"看台坐满了。大部分是学生，穿校服的，一片一片。中间夹着街坊，还有几个看着像他老队友的人。"},{"t":"n","text":"他妈妈坐在第三排靠边的位置，穿了一件新的红外套，袖子有点长，手缩在里面。"},{"t":"n","text":"她的旁边坐着一个老太太，是巷子里的李奶奶。两个人一直在说话。"},{"t":"n","text":"场上是热身。程野穿着那件洗得发白的 7 号球衣，号码掉了一半，「7」上面那一横只剩一点。"},{"t":"n","text":"他运球，跑了两步，起跳，投了一个。进了。"},{"t":"n","text":"看台上有人喊「程教练」，喊得很整齐，喊了三遍。"},{"t":"n","text":"他抬手，冲看台那边摆了一下。"},{"t":"n","text":"比赛开始。前两节是体校学生打，打得很乱，很快，抢断了就往前冲，谁也不肯传。"},{"t":"n","text":"程野坐在替补席上，看得很认真，时不时站起来喊两句。"},{"t":"n","text":"第三节最后两分钟，他脱了外套，走到记录台前。"},{"t":"n","text":"全场站起来。"},{"t":"n","text":"他上场。跑得没有那些孩子快，但位置站得很准。球到他手上，他先看一眼，再传出去。"},{"t":"n","text":"有一次，他接到球，面前没有人。他没有立刻投，等了一下，等防守的人扑过来，才把球分到底角。"},{"t":"n","text":"底角那个孩子投进了。"},{"t":"n","text":"他退防的时候，脚步慢下来，用手撑了一下膝盖。"},{"t":"n","text":"第四节最后四十秒，比分咬得很紧。球又到了他手上。"},{"t":"n","text":"他在三分线外，站了一下。全场都安静了。"},{"t":"n","text":"他起跳，投出去。"},{"t":"n","text":"球在篮筐上弹了一下，弹起来，落在篮筐上，又滚了一圈。"},{"t":"n","text":"没进。"},{"t":"n","text":"篮板被对方拿到。比赛结束的哨声响了。"},{"t":"n","text":"看台上安静了半秒，然后开始鼓掌。掌声从看台一头推到另一头。"},{"t":"n","text":"他站在场上，抬头看着篮筐，看了两秒。"},{"t":"n","text":"然后他笑了。笑得很大，露出那颗小虎牙，肩膀都在抖。"},{"t":"n","text":"有学生从看台上跳下来，跑到场上，围住他。"},{"t":"n","text":"工作人员搬了一张桌子到场地中央，桌上一支话筒。"},{"t":"n","text":"他被人推到桌子前面。看台上安静下来。"},{"t":"n","text":"他握着话筒，想了很久。话筒里传出他的呼吸声。"},{"t":"c","id":"chengye","text":"我叫程野。"},{"t":"n","text":"看台上有人笑。"},{"t":"c","id":"chengye","text":"七岁那年，我在我家饭馆门口挡了一辆溜坡的三轮车。"},{"t":"n","text":"他停了一下。"},{"t":"c","id":"chengye","text":"我眉上这道疤，就是那时候留的。"},{"t":"n","text":"他抬手，指了一下自己的左眉。"},{"t":"c","id":"chengye","text":"我妈说，我那时候哭得整条巷子都听见了。"},{"t":"n","text":"看台上笑成一片。第三排那个红外套的人低下头，肩膀动了一下。"},{"t":"c","id":"chengye","text":"我跑得快。从小到大，别人都这么说。"},{"t":"n","text":"他把话筒换到另一只手。"},{"t":"c","id":"chengye","text":"我自己也这么觉得。我觉得我什么都能追上。"},{"t":"n","text":"他的声音低了一点。"},{"t":"c","id":"chengye","text":"后来我发现，追不上的东西挺多的。"},{"t":"n","text":"看台上没有人说话。空调的风机在头顶响。"},{"t":"c","id":"chengye","text":"我妈的腰，我追不上。我家那个店，我追不上。二十岁那年的成绩，我追不上。"},{"t":"n","text":"他抬起头，往看台中间看。"},{"t":"c","id":"chengye","text":"我这辈子，跑得挺快的。就是有个人，一直没追上。"},{"t":"n","text":"看台上有人起哄，有人笑，笑声里有别的东西。"},{"t":"n","text":"他在人群里找你。"},{"t":"n","text":"找到了。"},{"t":"c","id":"chengye","text":"今天追上了。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"站起来，走下去","hint":"走下去 · 全场都看着","eff":{"aff":8.0,"happy":6.0,"stress":-4.0,"flag2":true,"lover":true},"reply":[{"t":"n","text":"你从看台上站起来。"},{"t":"n","text":"旁边的学生让开一条路。"},{"t":"n","text":"你走下台阶，一级，两级，走到场地边上，跨过那条广告带。"},{"t":"n","text":"他站在场地中央，冲你伸出手。"},{"t":"n","text":"你走过去，握住。他的手很热，手心全是汗。"},{"t":"n","text":"看台上开始欢呼。有人在拍手，有人在吹口哨，有一个小孩喊「教练牛逼」。"},{"t":"n","text":"他握着你的手，没有松。"},{"t":"c","id":"chengye","text":"我跑完了。"},{"t":"n","text":"你说嗯。"},{"t":"c","id":"chengye","text":"以后不跑了。"},{"t":"n","text":"你说嗯。"},{"t":"n","text":"他笑了一下，笑得有点没辙。"},{"t":"c","id":"chengye","text":"你别光嗯啊。"},{"t":"n","text":"你说，那你以后干嘛。"},{"t":"c","id":"chengye","text":"带你去看我带的队。"},{"t":"n","text":"他说。"},{"t":"c","id":"chengye","text":"第一排。我给你留。"}]},{"label":"B","text":"坐在原地，笑着鼓掌","hint":"笑一笑 · 也算回答","eff":{"aff":2.0,"happy":-3.0,"stress":2.0},"reply":[{"t":"n","text":"你鼓掌。"},{"t":"n","text":"他往这边看，看了一会儿，也笑了。"},{"t":"n","text":"他冲你点了点头。"},{"t":"n","text":"那个点头很轻，像在说「知道了」。"},{"t":"n","text":"散场以后，看台上的人慢慢走空。"},{"t":"n","text":"你在体育馆门口站了一会儿，手机亮了。"},{"t":"n","text":"他发来一条：「谢谢你来。」"},{"t":"n","text":"你打了一行字，删了。又打一行，又删了。"},{"t":"n","text":"最后你回：「恭喜。」"},{"t":"n","text":"他回了一个笑脸。"}]},{"label":"C","text":"比赛结束后，去后台找他","hint":"等散场 · 私下问","eff":{"aff":4.0,"eq":3.0,"happy":1.0},"reply":[{"t":"n","text":"后台在馆的侧面，一条窄走廊，堆着旧篮架和卷起来的地垫。"},{"t":"n","text":"他坐在一个箱子上，正把球衣脱下来，里面是一件旧 T 恤。"},{"t":"n","text":"看见你，他把球衣塞进包里。"},{"t":"c","id":"chengye","text":"你来了。"},{"t":"n","text":"你说，你刚才那话，什么意思。"},{"t":"n","text":"他挠了挠头，挠了很久，把头发挠得更乱。"},{"t":"c","id":"chengye","text":"字面意思。"},{"t":"n","text":"你说，那你说清楚点。"},{"t":"n","text":"他把包放在一边。"},{"t":"c","id":"chengye","text":"就是，我想跟你在一块。"},{"t":"n","text":"他说完，看着地面。"},{"t":"c","id":"chengye","text":"说了。就这样。"}]}]},{"t":"n","text":"人散得差不多了。工作人员在收球，一个个扔进筐里，嘣，嘣，嘣。"},{"t":"n","text":"他妈妈从看台上下来，红外套的袖子还是长，手缩在里面。"},{"t":"n","text":"她走到场地中央，抬头看那盏灯。"},{"t":"n","text":"「这馆子，我头一回来。」她说。"},{"t":"n","text":"程野走过去。"},{"t":"c","id":"chengye","text":"怎么样。"},{"t":"n","text":"「亮。」她说，「比咱们店里亮。」"},{"t":"n","text":"她转过身，看着自己的儿子，看了很久。"},{"t":"n","text":"「刚才那球，」她说，「差一点。」"},{"t":"n","text":"程野笑了。"},{"t":"c","id":"chengye","text":"差一点。"},{"t":"n","text":"「差一点也行。」她说，「你爸当年，连差一点都没有。」"},{"t":"n","text":"她把手从袖子里伸出来，拍了拍他的胳膊。"},{"t":"n","text":"那只手，指关节很大，冬天裂的口子还没好。"}],"id":"chengye_19"},{"no":20,"title":"第一排的票","week":55,"bg":"gym_day","cast":["chengye"],"steps":[{"t":"cast","list":["chengye"],"focus":"chengye"},{"t":"n","text":"体校的新馆是去年盖的，地板换了，灯光也换了，白色的，很亮，不刺眼。"},{"t":"n","text":"他在场边站着，穿一件深蓝色的教练服，胸口有个校徽。衣服有点大，肩线掉在胳膊上。"},{"t":"n","text":"脖子上挂着一个哨子，哨子上有一道很深的牙印。"},{"t":"n","text":"场上跑的是十三四岁的孩子，二十来个，分成两组打半场。"},{"t":"n","text":"他一直在喊。"},{"t":"c","id":"chengye","text":"回防！回防！你站着看什么呢！"},{"t":"n","text":"他的嗓子是哑的，喊到一半会破一下。"},{"t":"n","text":"有个孩子上篮被盖了，坐在地上不起来。他走过去，蹲下，把小孩拉起来。"},{"t":"c","id":"chengye","text":"起来。被盖了就被盖了，下一球打回来。"},{"t":"n","text":"训练结束，孩子们排队去喝水。他站在场边，用毛巾擦脸。"},{"t":"n","text":"看见你，他把毛巾挂回脖子上。"},{"t":"c","id":"chengye","text":"来了。"},{"t":"n","text":"他从兜里掏出一张票，票面有点软，被他揣了很久。"},{"t":"c","id":"chengye","text":"第一排。"},{"t":"n","text":"你接过来看。是青少年组的比赛，看台只有两排。"},{"t":"c","id":"chengye","text":"我们这边看台小。第一排就两排。"},{"t":"n","text":"他说着，自己也笑了。"},{"t":"c","id":"chengye","text":"反正你来了就是第一排。"},{"t":"n","text":"训练馆的暖气开得足。你们在场边的长椅上坐下。"},{"t":"n","text":"他把哨子摘下来，放在腿上。"},{"t":"n","text":"过了一会儿，他说："},{"t":"c","id":"chengye","text":"我这个月工资四千二。"},{"t":"n","text":"他说得很平静。"},{"t":"c","id":"chengye","text":"我妈手术的钱，还有六万没还完。一个月还两千。"},{"t":"n","text":"他算了一下。"},{"t":"c","id":"chengye","text":"还有三年。"},{"t":"n","text":"他抬起头。"},{"t":"c","id":"chengye","text":"你在那边，工作挺好的吧。"},{"t":"n","text":"你说还行。"},{"t":"n","text":"他点头，点得很慢。"},{"t":"c","id":"chengye","text":"我不去你那边。"},{"t":"n","text":"他说。"},{"t":"c","id":"chengye","text":"我妈在这儿。这条巷子她住了三十年。她走了，就真没人了。"},{"t":"n","text":"他把哨子在手里转。"},{"t":"c","id":"chengye","text":"所以，得你想。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"说「那我回来」","hint":"把话说重 · 想清楚","eff":{"aff":6.0,"happy":4.0,"stress":3.0},"reply":[{"t":"n","text":"他猛地抬头。"},{"t":"c","id":"chengye","text":"你别。"},{"t":"n","text":"他说得很快。"},{"t":"c","id":"chengye","text":"你这工作，好不容易。"},{"t":"n","text":"你说，你先别急着拒绝。"},{"t":"n","text":"他张了张嘴，又合上。"},{"t":"n","text":"过了很久，他说："},{"t":"c","id":"chengye","text":"你要是真回来，我不拦你。"},{"t":"n","text":"他看着你。"},{"t":"c","id":"chengye","text":"但我不要你是因为我才回来的。"}]},{"label":"B","text":"说「那就先这样」","hint":"把问题放回原处","eff":{"aff":3.0,"happy":-2.0,"stress":2.0},"reply":[{"t":"n","text":"他点头。"},{"t":"c","id":"chengye","text":"行。"},{"t":"n","text":"他把哨子挂回脖子上。"},{"t":"c","id":"chengye","text":"先这样。"},{"t":"n","text":"场上有孩子喊他。他站起来，走了两步，回头。"},{"t":"c","id":"chengye","text":"你别觉得我是在等你啊。"},{"t":"n","text":"他说完就跑了。跑得还是很快。"}]},{"label":"C","text":"说「有没有想过，让你妈也过去」","hint":"换个角度 · 算一算","eff":{"aff":4.0,"eq":2.0,"happy":1.0},"reply":[{"t":"n","text":"他愣住了。"},{"t":"n","text":"好像这个问题，他从来没有想过。"},{"t":"c","id":"chengye","text":"她——"},{"t":"n","text":"他把哨子拿在手里，捏了捏。"},{"t":"c","id":"chengye","text":"她在这条巷子住了三十年。门口那棵槐树，是她嫁过来那年种的。"},{"t":"n","text":"他抬起头。"},{"t":"c","id":"chengye","text":"她走了，那树怎么办。"},{"t":"n","text":"你说，树不用人管。"},{"t":"n","text":"他笑了一下。"},{"t":"c","id":"chengye","text":"也是。"}]}]},{"t":"n","text":"训练结束，孩子们跑过来，围着他喊「程教练」。"},{"t":"n","text":"他一个一个拍头，拍到最后一个，那个小孩躲了一下，还是被拍到了。"},{"t":"n","text":"有个小孩看见你，问：「教练，这是谁啊。」"},{"t":"n","text":"他把毛巾往肩上一搭。"},{"t":"c","id":"chengye","text":"我朋友。"},{"t":"n","text":"「哪个朋友。」小孩追问。"},{"t":"n","text":"他想了想。"},{"t":"c","id":"chengye","text":"坐第一排的那个。"},{"t":"n","text":"小孩「哦」了一声，跑开了，跑了两步又回头看了一眼。"},{"t":"n","text":"他站在场地中央，灯光从头顶落下来，把地板照得很亮。"},{"t":"n","text":"他把哨子放进嘴里，吹了一声。"},{"t":"n","text":"他把哨子从脖子上摘下来，放在腿上，用拇指擦了擦上面那道牙印。"},{"t":"c","id":"chengye","text":"你觉得我这样行吗。"},{"t":"n","text":"你说行。"},{"t":"n","text":"他点头，把哨子挂回去。"},{"t":"n","text":"过了一会儿，他说："},{"t":"c","id":"chengye","text":"我以前老觉得，不跑了，我就没什么用了。"},{"t":"n","text":"他把手撑在长椅上。"},{"t":"c","id":"chengye","text":"现在带着他们，好像也还行。"},{"t":"n","text":"孩子们又跑起来了。"}],"id":"chengye_20","judgeAfter":true}]},{"id":"finale","title":"终章 · 三结局","scenes":[{"no":21,"title":"第一排","week":60,"bg":"gym_day","cast":["chengye"],"steps":[{"t":"cast","list":["chengye"],"focus":"chengye"},{"t":"n","text":"他退役以后，在体校当了教练。"},{"t":"n","text":"工资不高，一个月四千多，涨得也慢。但他每天六点起床，比谁都精神。"},{"t":"n","text":"他带的那批孩子，两年后有一半进了市队。有一个进了省队，走的那天，他在训练馆门口站了很久。"},{"t":"n","text":"你们领证是秋天。"},{"t":"n","text":"他非要用跑步的方式去民政局。"},{"t":"n","text":"那天早上，他穿着西装，从体校出发，一路跑到民政局。他带的六个学生跟在后面。"},{"t":"n","text":"跑了两条街，到民政局门口的时候，全都喘得说不出话。"},{"t":"n","text":"有一个学生扶着墙，弯着腰，说：「教练，你、你是不是有毛病。」"},{"t":"n","text":"你站在民政局门口。"},{"t":"n","text":"他弯着腰喘气，手里的花束被压扁了，包装纸皱成一团。"},{"t":"n","text":"他抬起头，脸是红的，头发全湿了，西装外套不知道什么时候脱了，搭在胳膊上。"},{"t":"c","id":"chengye","text":"我……我跑得还行吧。"},{"t":"n","text":"你说：「慢死了。」"},{"t":"n","text":"他笑起来，露出那颗小虎牙。笑得站不直，扶着膝盖还在笑。"},{"t":"n","text":"学生们在后面起哄。"},{"t":"n","text":"你把手伸出去。他把花递过来，递到一半，又收回去，从西装内袋里摸出一样东西。"},{"t":"n","text":"是那只旧护腕。黑色的，边已经起毛，内侧那两个字还在。"},{"t":"n","text":"「别怕。」"},{"t":"n","text":"他把护腕套在你手腕上。还是太大，松松地挂着。"},{"t":"c","id":"chengye","text":"这个，物归原主。"},{"t":"n","text":"你说，这本来是你的。"},{"t":"c","id":"chengye","text":"现在是你的。"},{"t":"n","text":"楼下有人放了一挂小鞭炮，响声很短，然后是一阵烟。"},{"t":"n","text":"领完证，在他家巷口摆了几桌。"},{"t":"n","text":"那家店盘回来了。他妈妈的手术做了，恢复得不错，闲不住，又想把店开起来。"},{"t":"n","text":"招牌还是原来那块，只是漆重新描了一遍。旁边加了一块小木牌，上面写着：「老店重开」。"},{"t":"n","text":"木牌是他自己写的，字还是那么丑。"},{"t":"n","text":"摆了四桌。街坊、老队友、体校的学生、你的同事，挤了满满一条巷子。"},{"t":"n","text":"他妈妈忙前忙后，一直在说「多吃点，多吃点」，围裙都没解。"},{"t":"n","text":"你坐在他旁边，看他给每个人倒汽水。"},{"t":"n","text":"倒到第三桌，瓶子空了，他举着空瓶愣了一下，然后大声喊：「妈！再来一瓶！」"},{"t":"n","text":"他妈妈在后厨应了一声。"},{"t":"n","text":"你忽然觉得，这个人好像一直都没变。"},{"t":"n","text":"散席以后，天黑了。巷子里的灯泡换成了新的，比从前亮。"},{"t":"n","text":"他坐在店门口的台阶上，西装外套搭在腿上，领带松了。"},{"t":"n","text":"你在他旁边坐下。"},{"t":"n","text":"他把头靠过来，靠在你肩上。他身上有汽水的甜味，还有一点油烟味。"},{"t":"c","id":"chengye","text":"我今天跑了三公里。"},{"t":"n","text":"他说。"},{"t":"c","id":"chengye","text":"三点几公里。我算过。"},{"t":"n","text":"你说，累不累。"},{"t":"n","text":"他闭上眼睛。"},{"t":"c","id":"chengye","text":"累。"},{"t":"n","text":"过了一会儿。"},{"t":"c","id":"chengye","text":"但是到得早。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"说「以后每天都到这么早」","hint":"把日子说长","eff":{"aff":4.0,"happy":3.0},"reply":[{"t":"n","text":"他闭着眼睛笑。"},{"t":"c","id":"chengye","text":"那我得起更早。我五点半起来。"},{"t":"n","text":"你说五点半太早了。"},{"t":"c","id":"chengye","text":"不早。我习惯了。"}]},{"label":"B","text":"什么都不说，让他靠着","hint":"不打扰 · 就这样","eff":{"aff":3.0,"happy":2.0,"stress":-2.0},"reply":[{"t":"n","text":"他的呼吸慢慢沉下去。"},{"t":"n","text":"巷子里有人在收摊，铁架子碰在一起，响了两声。"},{"t":"n","text":"他没有醒。"}]},{"label":"C","text":"说「你还欠我一碗面」","hint":"把话拉回开头","eff":{"aff":5.0,"happy":3.0},"reply":[{"t":"n","text":"他睁开眼睛，愣了一下，然后笑得肩膀直抖。"},{"t":"c","id":"chengye","text":"欠你多少年了。"},{"t":"n","text":"他站起来，把西装外套往肩上一搭。"},{"t":"c","id":"chengye","text":"走。现在煮。"}]}]}],"quality":{"high":["日子很热闹。他嗓门大，楼道里的回声也大。","早上六点，他带着早训的队员在操场热身。你有时候嫌他吵，但家里从来没冷过。","他带的队后来拿了市里的冠军。颁奖那天，他站在场边，没有上场。","散场以后，他把奖牌挂在了你脖子上。"],"mid":["他还是会忘记纪念日。有一年，他记成了前一天，提前一天买了花，你笑了很久。","他还是会练球练到很晚。回来的时候轻手轻脚，怕吵醒你，其实你醒着。","但他记得你不吃香菜，记得你下雨天膝盖疼，记得你哪天有会要开。","有一年冬天你病了，他请了三天假，煮了三天的粥，一天比一天难吃。"],"low":["他把太多时间给了球场和学生。","早上出门的时候你还没醒，晚上回来的时候你已经睡了。","你有时候会觉得，自己排在很多东西后面：排在那些孩子后面，排在那块招牌后面。","有一年，他带队去外地比赛，走了半个月。回来那天，你在客厅坐着，灯没开。","他站在门口，手里拎着行李，很久没说话。","后来他把行李放下，走过来，在你旁边坐下。","程野（worried）：「我是不是……有点儿过分了。」","你没有回答。他也没有再问。"]},"id":"chengye_21","ending":"stay","endingName":"结局一 · 第一排"},{"no":22,"title":"以后有事，还找我","week":60,"bg":"cafe","cast":["chengye"],"steps":[{"t":"cast","list":["chengye"],"focus":"chengye"},{"t":"n","text":"他结婚是在春天。"},{"t":"n","text":"新娘是队里的队医，笑起来很温柔。他受伤那年，是她给他缠的绷带。"},{"t":"n","text":"婚礼在酒店二楼，摆了二十桌。"},{"t":"n","text":"你去了。你帮忙搬了一下午的喜糖，把一箱一箱的糖从车上搬到宴会厅。"},{"t":"n","text":"他穿着西装，站在门口迎客。领结有点歪。"},{"t":"n","text":"你走过去，他看见你，愣了一下，然后笑了。"},{"t":"c","id":"chengye","text":"你来了。"},{"t":"n","text":"你说恭喜。"},{"t":"n","text":"他伸手想拍你的肩，手抬到一半，落到你胳膊上，拍了两下。"},{"t":"n","text":"他的手很热。"},{"t":"n","text":"新娘在门口迎客，穿白裙子，看见你，主动伸出手。"},{"t":"n","text":"「他常提起你。」她说，「说你以前每场都来。」"},{"t":"n","text":"你说没有每场。"},{"t":"n","text":"她笑了一下：「他说每场。」"},{"t":"n","text":"程野在旁边站着，手插在裤兜里，听见了，没接话，只是把领结正了正。领结还是歪的。"},{"t":"n","text":"婚礼上他讲话，说得磕磕巴巴。说到一半，台下有人喊「程教练」，他笑了，说：「今天不叫教练。」"},{"t":"n","text":"敬茶的时候，他端着杯子，手有点抖。"},{"t":"n","text":"他妈妈坐在主桌，穿了件深色的外套，一直在给人夹菜。"},{"t":"n","text":"她看见你，招手让你过去，往你手里塞了一个红包。"},{"t":"n","text":"你说不用。她按住你的手，力气很大。"},{"t":"n","text":"「拿着。」她说，「你以前在我们家吃过那么多碗面。」"},{"t":"n","text":"红包很薄。你捏了捏，里面是一张纸，不是钱。"},{"t":"n","text":"后来你在洗手间打开。是一张旧菜单，塑封的，边角卷着。背面用圆珠笔写了一行字：「常来。」"},{"t":"n","text":"散场的时候，人走得差不多了。他把你送到酒店门口。"},{"t":"n","text":"外面在下小雨。他站在檐下，看着雨。"},{"t":"c","id":"chengye","text":"以后有事，还找我。"},{"t":"n","text":"你说好。"},{"t":"n","text":"你们都知道，不会有事了。"},{"t":"n","text":"他把西装外套脱下来，想给你挡雨。你说不用，你带了伞。"},{"t":"n","text":"他从口袋里摸出一包喜糖，塞到你手里。"},{"t":"c","id":"chengye","text":"拿着。我妈让每个人都拿。"},{"t":"n","text":"后来你偶尔在朋友圈看见他。"},{"t":"n","text":"他晒学生，晒比赛。有一张是他带的学生在球场上跑，跑得歪歪扭扭，他在后面追。"},{"t":"n","text":"你点过赞。他回一个笑脸。"},{"t":"n","text":"有一年校庆，你们在操场碰见。"},{"t":"n","text":"他胖了一点，嗓门还是那么大。离着十几米就喊你的名字。"},{"t":"c","id":"chengye","text":"哎，你最近怎么样？"},{"t":"n","text":"你说挺好。"},{"t":"n","text":"他说：「那就好。」"},{"t":"n","text":"两个人站在操场边上，看了一会儿。"},{"t":"n","text":"他想说什么，上课铃响了。"},{"t":"n","text":"他冲你摆摆手，跑向操场。"},{"t":"n","text":"跑得还是很快。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"说「你也保重」","hint":"一句足够","eff":{"aff":3.0,"happy":1.0},"reply":[{"t":"n","text":"他没有回头，只是把手举起来，往下压了一下。"},{"t":"n","text":"那个手势的意思，你过了两年才想明白，是「放心」。"}]},{"label":"B","text":"问他学生怎么样","hint":"聊点他的事","eff":{"aff":4.0,"happy":2.0,"eq":1.0},"reply":[{"t":"n","text":"他在操场中间停下，转回来，走了几步。"},{"t":"c","id":"chengye","text":"有个孩子，跑得比谁都快，就是不听话。"},{"t":"n","text":"他笑了一下。"},{"t":"c","id":"chengye","text":"跟我小时候一样。"},{"t":"n","text":"他说完，冲你摆摆手，又跑回去。"}]},{"label":"C","text":"什么都不说，看他跑","hint":"看着就行","eff":{"aff":2.0,"happy":2.0,"stress":-1.0},"reply":[{"t":"n","text":"他跑进队伍里，把口哨放进嘴里，吹了一声。"},{"t":"n","text":"学生们跟着他跑起来，跑得歪歪扭扭。"},{"t":"n","text":"你在操场边站着，站到下课铃响。"},{"t":"n","text":"你站在操场边，看他把队伍排成两列。有个学生迟到了，从教学楼那边跑过来，他冲那个学生喊了一句什么，学生笑了。"},{"t":"n","text":"风把操场上的白线吹得看不清了。"},{"t":"n","text":"你转身往外走。走到校门口，手机亮了一下。"},{"t":"n","text":"他发来一条：「刚才忘了问你，吃饭了没。」"},{"t":"n","text":"你回：「吃了。」"},{"t":"n","text":"他回了一个「好」字。后面跟着一句：「下次回来，提前说。我去车站接你。」"},{"t":"n","text":"回去的地铁上，你把那包喜糖拆开。里面是两块巧克力和一颗硬糖。"},{"t":"n","text":"硬糖的包装纸皱了。你把它展平，夹进书里。"},{"t":"n","text":"那颗糖后来一直没吃。化了，粘在纸上。"}]}]}],"quality":{"high":["你后来也过得很好。","你只是偶尔会想起，那个在雨里投篮的少年。想起的时候，不难受。","有一年你搬家，在旧箱子里翻出那只护腕。你把它洗干净，放进了新抽屉。"],"mid":["你们偶尔在群里说话。他还是爱发语音，每条都很长，前五秒全是「喂喂喂」。","他带队拿了第一个冠军，庆功宴你去了。他端着可乐敬全场，敬得像端着一个奖杯。","你笑他。他说：「你别笑。当教练比打球难。」"],"low":["你把那个护腕留了很多年。搬了几次家，不知道放哪了。","有一次你在电视上看见他。他带队比赛，站在场边，穿深蓝色的教练服。","镜头一晃就过去了。","你没有换台，看完了那场球。"]},"id":"chengye_22","ending":"miss","endingName":"结局二 · 以后有事，还找我"},{"no":23,"title":"第一排的票","week":60,"bg":"gym_day","cast":["chengye"],"steps":[{"t":"cast","list":["chengye"],"focus":"chengye"},{"t":"n","text":"你们做了一辈子的朋友。"},{"t":"n","text":"他当教练以后，每次比赛都给你留第一排的票。"},{"t":"n","text":"青少年组的比赛，看台只有两排。第一排离场地很近，能听见球鞋摩擦地板的声音。"},{"t":"n","text":"你去了很多次。第一排的位置，他一直给你留着。"},{"t":"n","text":"比赛结束，他冲你挥挥手，让你等等他。"},{"t":"n","text":"有一年暑假，你天天下午去。他给你留了场边最舒服的位置。"},{"t":"n","text":"训练结束，他总爱拽着你复盘今天的战术，讲哪个队员有长进，讲食堂今天又做了什么。"},{"t":"n","text":"你听着，偶尔损他两句。"},{"t":"n","text":"第二天你去得晚，训练已经开始了。"},{"t":"n","text":"他蹲在地上，手把手地掰一个队员的姿势。一个投篮动作，掰了十几遍。"},{"t":"n","text":"「手腕。手腕要压下去。」他说，「不是胳膊使劲，是手腕。」"},{"t":"n","text":"认真得像在教国家队。"},{"t":"n","text":"有个队员一直投不进，急了，把球往地上一砸。"},{"t":"n","text":"他走过去，把球捡起来，塞回那孩子手里。"},{"t":"c","id":"chengye","text":"砸球没用。球不疼。"},{"t":"n","text":"那孩子笑了。他也笑。"},{"t":"n","text":"他把那孩子的手举起来，摆成投篮的姿势，自己退后两步，蹲下来看。"},{"t":"c","id":"chengye","text":"再来。投十个。投不进也算。"},{"t":"n","text":"十个球，那孩子投进了两个。"},{"t":"c","id":"chengye","text":"两个。"},{"t":"n","text":"他伸出两根手指。"},{"t":"c","id":"chengye","text":"昨天一个都没有。"},{"t":"n","text":"他脖子上那个哨子，还是那道牙印。你问他为什么不换。"},{"t":"c","id":"chengye","text":"换了吹不响。"},{"t":"n","text":"你说新的怎么会吹不响。"},{"t":"n","text":"他把哨子放进嘴里，吹了一声，很响。"},{"t":"c","id":"chengye","text":"你听。这个是好的。"},{"t":"n","text":"那孩子投进了，他站起来，拍了一下那孩子的头。"},{"t":"n","text":"那孩子问他：「程教练，你以前很厉害吗？」"},{"t":"n","text":"他想了想。"},{"t":"c","id":"chengye","text":"厉害。"},{"t":"n","text":"他说。"},{"t":"c","id":"chengye","text":"当年有个朋友，每场都坐在第一排。"},{"t":"n","text":"你坐在第一排，冲他竖了个大拇指。"},{"t":"n","text":"他笑了，露出那颗小虎牙。眼角的纹路比从前深了。"},{"t":"n","text":"训练结束，孩子们散了。他把球一个一个捡进筐里。"},{"t":"n","text":"你走过去帮他。"},{"t":"n","text":"捡到最后一个，他抱着球，站在场地中央，抬头看那盏灯。"},{"t":"c","id":"chengye","text":"我有时候想，要不是那年你来了球场。"},{"t":"n","text":"他停住。"},{"t":"c","id":"chengye","text":"算了。不想这个。"},{"t":"n","text":"他把球扔进筐里。"},{"t":"c","id":"chengye","text":"反正你来了。"},{"t":"n","text":"散场以后，你们一起走出体育馆。天已经黑了，路灯亮着。"},{"t":"n","text":"他把训练馆的门锁上。钥匙串上挂着一个小小的篮球，橡胶的，掉了色。"},{"t":"n","text":"你问这个哪来的。"},{"t":"c","id":"chengye","text":"学生送的。去年教师节。"},{"t":"n","text":"他把钥匙放进口袋，拍了拍。"},{"t":"n","text":"你们在门口分开。他往宿舍走，走了几步，回头。"},{"t":"c","id":"chengye","text":"路上小心。"},{"t":"n","text":"你说你也是。"},{"t":"n","text":"他抬手挥了一下，转身走进那条没有灯的小路。脚步声很远都还听得见。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"说「我一直在第一排」","hint":"把话说完整","eff":{"aff":4.0,"happy":3.0},"reply":[{"t":"n","text":"他在黑里停了一下。"},{"t":"c","id":"chengye","text":"我知道。"},{"t":"n","text":"他的声音从黑里传出来。"},{"t":"c","id":"chengye","text":"我一直知道。"}]},{"label":"B","text":"说「以后别留票了，我自己来」","hint":"不占那个位置","eff":{"aff":3.0,"happy":2.0,"eq":1.0},"reply":[{"t":"n","text":"他笑了一声。"},{"t":"c","id":"chengye","text":"那不行。位置是我留的。"},{"t":"n","text":"他往前走。"},{"t":"c","id":"chengye","text":"你坐不坐是你的事，我留不留是我的事。"}]},{"label":"C","text":"拍他一下，说「跑吧」","hint":"一个字 · 就够","eff":{"aff":5.0,"happy":2.0},"reply":[{"t":"n","text":"你抬手，在他背上拍了一下。"},{"t":"n","text":"他回头，眉毛挑起来。"},{"t":"c","id":"chengye","text":"跑？"},{"t":"n","text":"你说跑。"},{"t":"n","text":"他真的跑起来了。跑进那条小路，几步就看不见了。"}]}]}],"quality":{"high":["你们两家人一起吃过很多次饭。他妈妈做的酥肉，你一个人能吃两碗。","有一年他带队拿了冠军，庆功宴上他喝的是汽水，喝得像喝了酒一样，站在椅子上讲话。","讲到最后，他说：「谢谢我朋友。坐第一排那个。」"],"mid":["你们不常联系。一年也就见两三次。","但每次见面，都不用重新熟悉。他从球场那头喊一声，你就知道是他。","有一年他搬家，你去帮忙。搬完他煮了面，还是卧一个蛋。"],"low":["后来他去了另一个城市，带一支职业青年队。走之前给你打过电话，你在开会，没接到。","你回过去的时候，他已经在高速上了。","他说：「没事。就是跟你说一声。」","那之后，你们的联系变成了每年一条消息。","但你一直留着那张第一排的票。票根压在书里，纸已经发黄了。"]},"id":"chengye_23","ending":"friend","endingName":"结局三 · 第一排的票"}]}],"events":[{"id":"cy1","title":"护腕（第 30 周后）","triggerWeek":30,"bg":"bedroom_day","cast":["chengye"],"intro":[{"t":"n","text":"早上起来，护腕还在手腕上。昨晚忘了摘，压出一道印。"},{"t":"n","text":"你把它摘下来，放在桌上。它自己摊开，像一只空着的手。"}],"opts":[{"label":"A","text":"戴回去","hint":"戴着 · 一整天","eff":{"aff":3.0,"happy":1.0},"reply":[{"t":"n","text":"上课的时候，你把手缩在袖子里。有人问是什么，你说是护腕。"}]},{"label":"B","text":"收进抽屉","hint":"放好 · 别丢了","eff":{"aff":1.0,"happy":2.0},"reply":[{"t":"n","text":"你把它叠好，压在抽屉最底下。晚上又拿出来看了一眼。"}]},{"label":"C","text":"洗了还他","hint":"洗干净 · 找机会还","eff":{"aff":2.0,"happy":1.0,"eq":1.0},"reply":[{"t":"n","text":"你用肥皂搓了两遍，晾在阳台上。干了以后，那两个字淡了一点。"}]}]},{"id":"cy2","title":"食堂的排骨（任意周）","triggerWeek":0,"bg":"classroom","cast":["chengye"],"intro":[{"t":"n","text":"食堂的排骨是限量供应。他来得晚，站在窗口看了一眼，空的。"}],"opts":[{"label":"A","text":"让给他","hint":"你还没动过","eff":{"aff":3.0,"happy":1.0},"reply":[{"t":"n","text":"他推了两次，还是接了。吃完把盘子端走，顺手把你的也端走了。"}]},{"label":"B","text":"分着吃","hint":"一人一半 · 别争","eff":{"aff":4.0,"happy":2.0},"reply":[{"t":"n","text":"他数了数，一共五块。他把三块拨给你，说：「我吃两块就够了。」"}]},{"label":"C","text":"自己吃","hint":"你也很饿","eff":{"aff":-1.0,"happy":1.0},"reply":[{"t":"n","text":"他坐在对面，看着你吃，说：「好吃吗。」你说好吃。他点点头，说：「那就行。」"}]}]},{"id":"cy3","title":"他家的饭馆（第 40 周后）","triggerWeek":40,"bg":"izakaya_night","cast":["chengye"],"intro":[{"t":"n","text":"他家店那天特别忙。门口停着一辆送货车，卸了一半的货堆在台阶上。"}],"opts":[{"label":"A","text":"去帮忙","hint":"系上围裙 · 干活","eff":{"aff":4.0,"familyRel":2.0,"str":1.0},"reply":[{"t":"n","text":"你端了一下午的菜。他妈妈临走塞给你一个打包盒，里面是双份的酥肉。"}]},{"label":"B","text":"去吃饭","hint":"照常来 · 点一碗","eff":{"aff":3.0,"happy":2.0},"reply":[{"t":"n","text":"他给你下面的时候多放了半勺肉。你说多了。他说：「不多。你今天看着瘦。」"}]},{"label":"C","text":"不去了","hint":"那天有别的事","eff":{},"reply":[{"t":"n","text":"晚上他发来一张照片：一张空桌子，桌上放着一碗没人动的面。下面写：「给你留的，凉了。」"}]}]},{"id":"cy4","title":"脚伤复查（第 45 周后）","triggerWeek":45,"bg":"hospital_day","cast":["chengye"],"intro":[{"t":"n","text":"复查的通知单贴在冰箱上，贴了半个月。"}],"opts":[{"label":"A","text":"陪他去","hint":"请半天假 · 一起去","eff":{"aff":5.0,"stress":-2.0,"happy":2.0},"reply":[{"t":"n","text":"他在走廊里排队，排到一半说：「其实我自己来就行。」你说你来了。他就不说了。"}]},{"label":"B","text":"打电话问","hint":"问一句 · 也算记得","eff":{"aff":2.0,"happy":1.0},"reply":[{"t":"n","text":"他说没事。你说真的假的。他说：「真的。就是医生说，别跑了。」然后他笑了一声。"}]},{"label":"C","text":"忘了","hint":"那几天太忙","eff":{"aff":-3.0,"stress":1.0},"reply":[{"t":"n","text":"晚上十一点，他发来一张片子，黑白的，看不懂。没有配字。你回了一个「？」。他回：「没事。」"}]}]},{"id":"cy5","title":"退役赛的票（第 51 周前）","triggerWeek":51,"bg":"gym_day","cast":["chengye"],"intro":[{"t":"n","text":"他把一张票放在你桌上，压在水杯底下。"}],"opts":[{"label":"A","text":"去","hint":"请一天假 · 去老馆","eff":{"aff":5.0,"happy":3.0},"reply":[{"t":"n","text":"你到的时候，他把第一排中间那个位置的塑料椅擦了两遍。"}]},{"label":"B","text":"送花","hint":"买束花 · 别太贵","eff":{"aff":3.0,"fin":-2.0,"happy":2.0},"reply":[{"t":"n","text":"他抱着花站在场地中央，不知道怎么拿，最后把花夹在胳膊底下，腾出手来投篮。"}]},{"label":"C","text":"不去","hint":"那天走不开","eff":{"aff":-2.0,"happy":-1.0},"reply":[{"t":"n","text":"散场以后他发来一段视频。他在场地中央说话，说得磕磕巴巴。视频只有三十秒，被他自己掐了。"}]}]},{"id":"cy6","title":"秒表（第 33 周后）","triggerWeek":33,"bg":"gym_day","cast":["chengye"],"intro":[{"t":"n","text":"他有一块秒表，塑料的，黑色的，表带断过一次，用胶粘上了。"}],"opts":[{"label":"A","text":"借来用","hint":"说你跑步要用","eff":{"aff":3.0,"str":1.0},"reply":[{"t":"n","text":"你拿它跑了半个月。还回去的时候，他按了一下，说：「你跑得比我慢多了。」"}]},{"label":"B","text":"还回去，顺便换了电池","hint":"换块电池 · 不说","eff":{"aff":4.0,"happy":2.0},"reply":[{"t":"n","text":"他按了两下，屏幕亮了。他看了你一眼，说：「你怎么知道它没电。」你说猜的。"}]},{"label":"C","text":"弄丢了","hint":"找不到了","eff":{"aff":-2.0,"stress":1.0},"reply":[{"t":"n","text":"你说你赔他一块。他说不用。第二天他自己买了一块一模一样的，还是把旧表带拆下来装上去。"}]}]},{"id":"cy7","title":"雨天的伞（任意周 · 雨）","triggerWeek":0,"bg":"sakura_path","cast":["chengye"],"intro":[{"t":"n","text":"下课的时候在下雨。他只带了一把伞，伞骨还断了一根。"}],"opts":[{"label":"A","text":"两个人打一把","hint":"挤一挤 · 肩膀湿一边","eff":{"aff":4.0,"happy":2.0},"reply":[{"t":"n","text":"他把伞往你这边偏。你说明显偏了。他说：「我这边淋不着。」"}]},{"label":"B","text":"跑回去拿","hint":"快 · 别淋着","eff":{"aff":2.0,"str":1.0,"happy":1.0},"reply":[{"t":"n","text":"他跑出去，跑得很快。回来的时候手里两把伞，自己那把没撑，整个人湿透了。"}]},{"label":"C","text":"各自淋","hint":"不远 · 走过去","eff":{"aff":1.0,"happy":2.0,"str":1.0},"reply":[{"t":"n","text":"两个人走进雨里，走了十分钟。到楼门口，他甩了甩头发，水珠溅到你脸上。"}]}]},{"id":"cy8","title":"凌晨的语音（第 55 周后）","triggerWeek":55,"bg":"bedroom_night","cast":["chengye"],"intro":[{"t":"n","text":"凌晨一点，手机亮了一下。他发来一条语音，六分十二秒。"}],"opts":[{"label":"A","text":"听完","hint":"戴耳机 · 一句一句听","eff":{"aff":5.0,"happy":3.0,"stress":-2.0},"reply":[{"t":"n","text":"语音里他讲了半天训练，讲食堂，讲一个孩子把球投到篮板上沿。最后十秒他没说话。然后说：「行了。睡了。」"}]},{"label":"B","text":"转成文字看","hint":"太长了 · 先扫一眼","eff":{"aff":2.0,"happy":1.0},"reply":[{"t":"n","text":"文字转得很乱，好多地方是「嗯」和「那个」。你看到最后一行，转写失败了。你回去听了那十秒。"}]},{"label":"C","text":"第二天再回","hint":"太困了 · 先睡","eff":{"aff":-1.0,"happy":-1.0},"reply":[{"t":"n","text":"第二天你回：「昨天睡了。」他回：「没事。也没什么重要的。」"}]}]}],"endingNames":{"stay":"结局一 · 第一排","miss":"结局二 · 以后有事，还找我","friend":"结局三 · 第一排的票"}};
